test('AS/RS 묶음 배출은 품목별 설정 수량이 적재될 때까지 셀에 보관한 뒤 출고한다',()=>{
  const equipment=[{id:'in',type:'source',source:{origin:'dxf'},parameters:{processTime:.01}},{id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:6,levels:1,productTypes:1,columnPitch:.1,levelHeight:.1,travelSpeed:10,liftSpeed:10,acceleration:10,forkStroke:.1,forkSpeed:2,forkAcceleration:10,forkDeceleration:10,putawayTime:.2,retrievalTime:.2,batchReleaseEnabled:1,releaseBatchSize:3}},{id:'out',type:'sink',source:{origin:'dxf'},parameters:{dischargeTime:.01}}],engine=new CadFlowEngine({equipment,cadSchematic:{edges:[{from:'in',to:'asrs'},{from:'asrs',to:'out'}]}},{injectA:1,simDuration:20});for(let index=0;index<1000;index++)engine.step(.02);const putaways=engine.state.events.filter(event=>event.type==='asrs-putaway'),firstRetrieval=engine.state.events.find(event=>event.type==='asrs-retrieval-start'),putawaysBefore=putaways.filter(event=>event.t<=firstRetrieval.t);assert.ok(firstRetrieval?.batch);assert.ok(putawaysBefore.length>=3);assert.deepEqual(putawaysBefore.slice(0,3).map(event=>event.target.index),[0,1,2]);assert.ok(engine.state.events.some(event=>event.type==='asrs-stored'));assert.ok(engine.state.events.some(event=>event.type==='asrs-mode-change'));
});

test('ASRS는 요청 라인 재고가 없으면 다른 라인 재고로 대체 출고하지 않는다',()=>{
  const equipment=[{id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:2,levels:1,productTypes:2,travelSpeed:10,liftSpeed:10}},{id:'out',type:'sink',source:{origin:'dxf'},parameters:{dischargeTime:.01}}],engine=new CadFlowEngine({equipment,cadSchematic:{edges:[{from:'asrs',to:'out'}]}},{injectA:30,simDuration:40});for(let index=0;index<200;index++)engine.step(.05);const [requested,other]=Object.values(engine.state.asrs.zones);other.inventory=1;engine.state.asrs.inventory=1;for(let index=0;index<100;index++)engine.step(.05);assert.equal(engine.state.completedProducts.length,0);assert.equal(other.inventory,1);requested.inventory=1;engine.state.asrs.inventory=2;for(let index=0;index<100;index++)engine.step(.05);assert.ok(engine.state.completedProducts.length>0);assert.equal(other.inventory,1);
});

test('ASRS 사이클은 목표 열과 층, 상승·하강 속도를 반영한다',()=>{
  const item={type:'stackerCrane',parameters:{rows:2,columns:8,levels:4,columnPitch:1.5,levelHeight:2,travelSpeed:3,liftSpeed:1,downSpeed:2,acceleration:1,putawayTime:4,retrievalTime:6,simultaneousMotion:1}};
  assert.deepEqual(asrsTargetCell(item,0),{index:0,column:0,level:0,row:0});
  assert.deepEqual(asrsTargetCell(item,17),{index:17,column:2,level:0,row:1});
  assert.ok(asrsCycleDuration(item,{slotIndex:63,operation:'putaway'})>asrsCycleDuration(item,{slotIndex:0,operation:'putaway'}));
  assert.notEqual(asrsCycleDuration(item,{slotIndex:17,operation:'putaway'}),asrsCycleDuration(item,{slotIndex:17,operation:'retrieval'}));
  assert.ok(acceleratedTravelTime(10,2,1)>0);
});

test('ASRS X·Y·Z축은 각 축의 속도와 가감속도로 독립 계산된다',()=>{const base={type:'stackerCrane',parameters:{rows:1,columns:4,levels:3,columnPitch:2,levelHeight:2,infeedColumn:1,infeedLevel:1,travelSpeed:2,travelAcceleration:1,travelDeceleration:1,liftSpeed:1,liftAcceleration:.5,liftDeceleration:.5,forkStroke:1,forkSpeed:.5,forkAcceleration:.5,forkDeceleration:.5,putawayTime:1}},profile=asrsCycleProfile(base,{slotIndex:8,operation:'putaway'}),fastX=asrsCycleProfile({type:'stackerCrane',parameters:{...base.parameters,travelAcceleration:4,travelDeceleration:4}},{slotIndex:8,operation:'putaway'}),fastZ=asrsCycleProfile({type:'stackerCrane',parameters:{...base.parameters,forkSpeed:1,forkAcceleration:2,forkDeceleration:2}},{slotIndex:8,operation:'putaway'});assert.ok(fastX.travel<profile.travel);assert.equal(fastX.lift,profile.lift);assert.ok(fastZ.fork<profile.fork);assert.equal(profile.fork,profile.forkOneWay*2+profile.forkDwell);});

test('AS/RS 입고와 출고는 서로 다른 인계 위치에서 목표 셀까지 거리를 계산한다',()=>{const item={type:'stackerCrane',parameters:{rows:1,columns:8,levels:4,columnPitch:2,levelHeight:1.5,infeedColumn:1,infeedLevel:1,outfeedColumn:8,outfeedLevel:2,travelSpeed:2,liftSpeed:1,downSpeed:1}},putaway=asrsCycleProfile(item,{slotIndex:12,operation:'putaway'}),retrieval=asrsCycleProfile(item,{slotIndex:12,operation:'retrieval'});assert.deepEqual([putaway.baseColumn,putaway.baseLevel],[0,0]);assert.deepEqual([retrieval.baseColumn,retrieval.baseLevel],[7,1]);assert.notEqual(putaway.horizontal,retrieval.horizontal);const outStart=asrsOperationSnapshot(item,{asrsPhase:'retrieval',nodeEnteredAt:0,asrsTarget:{index:12}},0);assert.deepEqual([outStart.x,outStart.y],[7,1]);});

test('AS/RS 출고 중에는 입고 물류가 직전 컨베이어 종료단을 점유하고 후속 물류도 충돌 대기한다',()=>{const cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,safetyGap:.2}},asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:2,levels:1,productTypes:1}},edge={from:'cv',to:'asrs'},engine=new CadFlowEngine({equipment:[cv,asrs],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{injectA:99,simDuration:10}),outbound=engine.prepareToken({id:1,nodeId:'asrs',edge:null,asrsPhase:'retrieval',asrsTarget:{index:0},readyAt:9}),front=engine.prepareToken({id:2,nodeId:'cv',edge:null,motion:engine.createMotion(cv),readyAt:0}),behind=engine.prepareToken({id:3,nodeId:'cv',edge:null,motion:engine.createMotion(cv),readyAt:0});front.progress=1;front.edge=edge;behind.progress=.92;engine.state.cadTokens=[outbound,front,behind];assert.equal(engine.holdAsrsInboundWhileBusy(),true);assert.equal(front.edge,null);assert.equal(front.progress,1);assert.equal(front.queueState,'ASRS작업대기');engine.applyOccupancyInterlocks(.02);assert.equal(behind.queueState,'Queue');});

test('AS/RS 입고 중에도 다음 입고를 차단하고 앞단 컨베이어까지 점유 인터락을 전파한다',()=>{const upstream={id:'up',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:1.2,speed:1,safetyGap:.2}},infeed={id:'infeed',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:1.2,speed:1,safetyGap:.2}},asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:2,levels:1,productTypes:1,stackerCount:1}},toInfeed={from:'up',to:'infeed'},toAsrs={from:'infeed',to:'asrs'},engine=new CadFlowEngine({equipment:[upstream,infeed,asrs],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[toInfeed,toAsrs]}},{injectA:99,simDuration:10}),activePutaway=engine.prepareToken({id:1,nodeId:'asrs',edge:null,asrsPhase:'putaway',asrsTarget:{index:0},readyAt:9}),waiting=engine.prepareToken({id:2,nodeId:'infeed',edge:null,motion:engine.createMotion(infeed),readyAt:0}),upstreamCargo=engine.prepareToken({id:3,nodeId:'up',edge:null,motion:engine.createMotion(upstream),readyAt:0});waiting.progress=1;waiting.edge=toAsrs;upstreamCargo.progress=1;upstreamCargo.edge=toInfeed;engine.state.cadTokens=[activePutaway,waiting,upstreamCargo];engine.resolveZeroDelayHandovers();assert.equal(waiting.nodeId,'infeed');assert.equal(waiting.edge,null);assert.equal(waiting.progress,1);assert.equal(waiting.queueState,'ASRS작업대기');assert.equal(engine.tryDirectHandover(upstreamCargo),false);assert.equal(upstreamCargo.nodeId,'up');});

test('AS/RS 스태커 인터락은 시작 설비 라인별로 독립 실행된다',()=>{const makeCv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:2,speed:1}}),lineA=makeCv('line-a'),lineB=makeCv('line-b'),asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:2,levels:1,productTypes:2,stackerCount:2,infeedTime:.1}},edgeA={from:'line-a',to:'asrs'},edgeB={from:'line-b',to:'asrs'},branches=[{name:'라인 A',nodeIds:['line-a']},{name:'라인 B',nodeIds:['line-b']}],engine=new CadFlowEngine({equipment:[lineA,lineB,asrs],cargoSpec:{length:.5,width:.4},cadSchematic:{inboundBranches:branches,edges:[edgeA,edgeB]}},{injectA:99,simDuration:10}),activeA=engine.prepareToken({id:1,nodeId:'asrs',edge:null,flowKey:'라인 A',asrsPhase:'retrieval',asrsTarget:{index:0},readyAt:9}),waitingA=engine.prepareToken({id:2,nodeId:'line-a',edge:null,flowKey:'라인 A',motion:engine.createMotion(lineA),readyAt:0}),waitingB=engine.prepareToken({id:3,nodeId:'line-b',edge:null,flowKey:'라인 B',motion:engine.createMotion(lineB),readyAt:0});waitingA.progress=1;waitingA.edge=edgeA;waitingB.progress=1;waitingB.edge=edgeB;engine.state.cadTokens=[activeA,waitingA,waitingB];engine.asrsBatchConfig();engine.resolveZeroDelayHandovers();engine.state.t=.1;engine.resolveZeroDelayHandovers();assert.equal(waitingA.nodeId,'line-a');assert.equal(waitingA.edge,null);assert.equal(waitingB.nodeId,'asrs');assert.equal(waitingB.asrsPhase,'putaway');assert.equal(engine.asrsLineBusy('라인 A'),true);assert.equal(engine.asrsLineBusy('라인 B'),true);});

test('AS/RS 앞 컨베이어가 작업 대기로 정지하면 상류 물류는 종료점에서 진입 대기한다',()=>{const upstream={id:'up',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:3,speed:1,safetyGap:.2}},infeed={id:'infeed',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:6,speed:1,safetyGap:.2}},asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:2,levels:1,productTypes:1}},toInfeed={from:'up',to:'infeed'},toAsrs={from:'infeed',to:'asrs'},engine=new CadFlowEngine({equipment:[upstream,infeed,asrs],cargoSpec:{length:1,width:.8},cadSchematic:{inboundBranches:[{name:'라인 A',nodeIds:['up','infeed']}],edges:[toInfeed,toAsrs]}},{injectA:99,simDuration:10}),active=engine.prepareToken({id:1,nodeId:'asrs',edge:null,flowKey:'라인 A',asrsPhase:'putaway',asrsTarget:{index:0},readyAt:9}),atEnd=engine.prepareToken({id:2,nodeId:'infeed',edge:null,flowKey:'라인 A',motion:engine.createMotion(infeed),readyAt:0}),following=engine.prepareToken({id:3,nodeId:'up',edge:null,flowKey:'라인 A',motion:engine.createMotion(upstream),readyAt:0});atEnd.progress=1;atEnd.edge=toAsrs;following.progress=1;following.edge=toInfeed;engine.state.cadTokens=[active,atEnd,following];engine.resolveZeroDelayHandovers();assert.equal(atEnd.nodeId,'infeed');assert.equal(atEnd.edge,null);assert.equal(atEnd.queueState,'ASRS작업대기');assert.equal(following.nodeId,'up');assert.equal(following.edge,toInfeed);});

test('새 프로젝트의 임의 라인명도 시작 설비에서 물류 라인으로 고정된다',()=>{const sources=['차체 1라인','모듈 X라인'].map((name,index)=>({id:`src-${index}`,type:'source',source:{origin:'dxf'},parameters:{processTime:1,cargoType:index?'트림 물류':'도어 물류'},name})),branches=sources.map((source,index)=>({name:index?'모듈 X라인':'차체 1라인',nodeIds:[source.id]})),engine=new CadFlowEngine({equipment:sources,cadSchematic:{inboundBranches:branches,edges:[]}},{injectA:30,simDuration:2});engine.step(.02);assert.deepEqual(engine.state.cadTokens.map(token=>token.flowKey),['차체 1라인','모듈 X라인']);assert.deepEqual(engine.state.cadTokens.map(token=>token.cargoType),['도어 물류','트림 물류']);});

test('라인 정보가 없는 새 프로젝트도 특정 현장명이 아닌 범용 품목명으로 초기화된다',()=>{const asrs={id:'store',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:3}},engine=new CadFlowEngine({equipment:[asrs],cadSchematic:{inboundBranches:[],edges:[]}},{simDuration:1});assert.deepEqual(Object.keys(engine.state.asrs.zones),['품목 1','품목 2','품목 3']);});

test('AS/RS 우측 모니터 상태는 엔진 작업시간과 목표 셀을 동일하게 사용한다',()=>{const item={type:'stackerCrane',parameters:{rows:2,columns:8,levels:4,columnPitch:1.5,levelHeight:2,travelSpeed:2.5,liftSpeed:1,downSpeed:1.2,acceleration:.5,putawayTime:4,retrievalTime:5}},token={asrsPhase:'putaway',nodeEnteredAt:10,asrsTarget:{index:17}},start=asrsOperationSnapshot(item,token,10),middle=asrsOperationSnapshot(item,token,15);assert.equal(start.status,'inbound');assert.equal(start.label,'입고중');assert.deepEqual(start.target,asrsTargetCell(item,17));assert.ok(middle.progress>start.progress);token.asrsPhase='retrieval';assert.equal(asrsOperationSnapshot(item,token,10).status,'outbound');assert.equal(asrsOperationSnapshot(item,null,10).label,'대기중');});

test('AS/RS 3D 사이클은 목표 이동·포크 신축·셀 적재·인출·원점 복귀를 실제 시간으로 구분한다',()=>{const item={type:'stackerCrane',parameters:{rows:2,columns:8,levels:4,columnPitch:1.5,levelHeight:2,travelSpeed:2.5,liftSpeed:1,downSpeed:1.2,acceleration:.5,putawayTime:4,retrievalTime:6}},target={index:17},putaway=asrsCycleProfile(item,{slotIndex:17,operation:'putaway'}),token={asrsPhase:'putaway',nodeEnteredAt:0,asrsTarget:target},travel=asrsOperationSnapshot(item,token,putaway.motion/2),forkIn=asrsOperationSnapshot(item,token,putaway.motion+putaway.fork*.25),stored=asrsOperationSnapshot(item,token,putaway.motion+putaway.fork*.75),returning=asrsOperationSnapshot(item,token,putaway.motion+putaway.fork+putaway.returnTime*.5);assert.equal(travel.phase,'travel');assert.ok(travel.x>0&&travel.y>=0);assert.equal(forkIn.phase,'fork');assert.ok(forkIn.forkExtension>0);assert.equal(forkIn.cargoMode,'crane');assert.equal(stored.cargoMode,'cell');assert.equal(returning.phase,'return');assert.ok(returning.x>0&&returning.x<putaway.target.column+1);token.asrsPhase='retrieval';const retrieval=asrsCycleProfile(item,{slotIndex:17,operation:'retrieval'}),beforePickup=asrsOperationSnapshot(item,token,retrieval.motion+retrieval.fork*.25),afterPickup=asrsOperationSnapshot(item,token,retrieval.motion+retrieval.fork*.75);assert.equal(beforePickup.cargoMode,'cell');assert.equal(afterPickup.cargoMode,'crane');assert.equal(retrieval.total,retrieval.motion+retrieval.fork+retrieval.returnTime);assert.ok(retrieval.outfeed>0);});

test('AS/RS 출고 인계는 하류 승인 전 원래 크기로 대기하고 승인 후에만 축소된다',()=>{const item={type:'stackerCrane',parameters:{rows:1,columns:4,levels:1,columnPitch:1,travelSpeed:2,downSpeed:1,retrievalTime:2,outfeedTime:2}},profile=asrsCycleProfile(item,{slotIndex:3,operation:'retrieval'}),token={asrsPhase:'retrieval',nodeEnteredAt:0,asrsTarget:{index:3}},waiting=asrsOperationSnapshot(item,token,profile.total+10);assert.equal(waiting.phase,'handoff-wait');assert.equal(waiting.cargoScale,1);token.handoffAcceptedAt=profile.total+10;const first=asrsOperationSnapshot(item,token,token.handoffAcceptedAt),middle=asrsOperationSnapshot(item,token,token.handoffAcceptedAt+profile.outfeed/2),end=asrsOperationSnapshot(item,token,token.handoffAcceptedAt+profile.outfeed);assert.equal(first.phase,'outfeed');assert.equal(first.cargoScale,1);assert.ok(middle.cargoScale>0&&middle.cargoScale<1);assert.equal(end.cargoScale,0);assert.deepEqual([first.x,first.y],[profile.baseColumn,profile.baseLevel]);assert.deepEqual([middle.x,middle.y],[profile.baseColumn,profile.baseLevel]);});

test('AS/RS 입고는 설정된 입고 인계 시간 동안 물류 전체를 받은 뒤 셀 이동을 시작한다',()=>{const item={type:'stackerCrane',parameters:{rows:1,columns:4,levels:1,infeedTime:2,columnPitch:1,travelSpeed:1,acceleration:1}},profile=asrsCycleProfile(item,{slotIndex:3,operation:'putaway'}),token={asrsPhase:'putaway',nodeEnteredAt:10,asrsTarget:{index:3}},start=asrsOperationSnapshot(item,token,10),middle=asrsOperationSnapshot(item,token,11),received=asrsOperationSnapshot(item,token,12),moving=asrsOperationSnapshot(item,token,12.5);assert.equal(profile.infeed,2);assert.equal(start.phase,'infeed');assert.equal(start.cargoScale,0);assert.equal(middle.phase,'infeed');assert.equal(middle.cargoScale,.5);assert.equal(received.phase,'travel');assert.equal(received.x,profile.baseColumn);assert.equal(moving.phase,'travel');assert.ok(moving.x>profile.baseColumn);});

test('AS/RS 입고 인계 중에는 물류를 상류 설비에 유지하고 완료 후에만 스태커 이동을 시작한다',()=>{const cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:2,speed:1}},asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:3,levels:1,infeedTime:2,productTypes:1}},edge={from:'cv',to:'asrs'},engine=new CadFlowEngine({equipment:[cv,asrs],cadSchematic:{edges:[edge],inboundBranches:[{name:'라인',nodeIds:['cv']}]}},{simDuration:10}),token=engine.prepareToken({id:1,nodeId:'cv',edge,flowKey:'라인',cargoType:'박스',readyAt:0});engine.state.cadTokens=[token];assert.equal(engine.tryDirectHandover(token),false);assert.equal(token.nodeId,'cv');assert.equal(token.transferState,'Transferring');assert.equal(token.asrsInfeedAcceptedAt,0);engine.state.t=1;assert.equal(engine.tryDirectHandover(token),false);assert.equal(token.nodeId,'cv');engine.state.t=2;assert.equal(engine.tryDirectHandover(token),true);assert.equal(token.nodeId,'asrs');assert.equal(token.asrsPhase,'putaway');assert.notEqual(asrsOperationSnapshot(asrs,token,2).phase,'infeed');});

test('일반 인계 루프도 AS/RS 입고시간을 우회하지 않고 확대 진행률과 소유권을 동기화한다',()=>{const cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:2,speed:1}},asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:1,levels:1,infeedTime:2,productTypes:1}},edge={from:'cv',to:'asrs'},layout={equipment:[cv,asrs],cargoSpec:{length:.5,width:.4},cadSchematic:{edges:[edge],inboundBranches:[{name:'라인',nodeIds:['cv']}]}},engine=new CadFlowEngine(layout,{simDuration:10}),token=engine.prepareToken({id:1,nodeId:'cv',edge,flowKey:'라인',cargoType:'박스',readyAt:0});engine.state.cadTokens=[token];engine.step(.02);assert.equal(token.nodeId,'cv');assert.ok(token.asrsInfeedAcceptedAt!=null);engine.step(.5);engine.step(.5);const middle=asrsOperationSnapshot(asrs,{...token,asrsPhase:'putaway',nodeEnteredAt:token.asrsInfeedAcceptedAt},engine.state.t);assert.ok(middle.infeedProgress>.4&&middle.infeedProgress<.6);assert.equal(token.nodeId,'cv');engine.step(.5);engine.step(.5);engine.step(.04);assert.equal(token.nodeId,'asrs');assert.equal(token.asrsInfeedAcceptedAt,null);});

test('AS/RS 출고는 컨베이어·AMR·AGV의 실제 수용 상태를 확인한 뒤 인계를 시작한다',()=>{for(const targetType of ['conveyor','amr','agv']){const asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:1,levels:1,outfeedTime:1}},target={id:'target',type:targetType,source:{origin:'dxf',parameterLengthUnit:'m'},parameters:targetType==='conveyor'?{length:3,speed:1}:{shuttleDistance:3,travelSpeed:1}},edge={from:'asrs',to:'target'},engine=new CadFlowEngine({equipment:[asrs,target],cargoSpec:{length:.5,width:.4},cadSchematic:{edges:[edge]}},{simDuration:10}),outbound=engine.prepareToken({id:1,nodeId:'asrs',edge,asrsPhase:'retrieval',asrsTarget:{index:0},nodeEnteredAt:0,readyAt:0}),busy=engine.prepareToken({id:2,nodeId:'target',edge:null,queueState:targetType==='conveyor'?'Queue':null,motion:engine.createMotion(target),readyAt:9});engine.state.t=asrsCycleProfile(asrs,{operation:'retrieval'}).total;engine.state.cadTokens=[outbound,busy];assert.equal(engine.tryDirectHandover(outbound),false);assert.ok(outbound.handoffAcceptedAt==null);assert.equal(asrsOperationSnapshot(asrs,outbound,engine.state.t).cargoScale,1);engine.state.cadTokens=[outbound];engine.stabilizeFlowPermissions(.02);assert.equal(engine.tryDirectHandover(outbound),false);assert.equal(outbound.transferState,'Transferring');assert.equal(outbound.nodeId,'asrs');engine.state.t=outbound.handoffAcceptedAt+.5;assert.ok(asrsOperationSnapshot(asrs,outbound,engine.state.t).cargoScale<1);engine.state.t=outbound.handoffAcceptedAt+1;engine.stabilizeFlowPermissions(.02);assert.equal(engine.tryDirectHandover(outbound),true);assert.equal(outbound.nodeId,'target');}});

test('AS/RS는 배출 완료 예상시점에 하류가 막힐 경우 미리 인출한 물류를 출고 위치에서 유지한다',()=>{const asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:1,levels:1,outfeedTime:1}},target={id:'target',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:3,speed:1}},edge={from:'asrs',to:'target'},engine=new CadFlowEngine({equipment:[asrs,target],cargoSpec:{length:.5,width:.4},cadSchematic:{edges:[edge]}},{simDuration:10}),token=engine.prepareToken({id:1,nodeId:'asrs',edge,asrsPhase:'retrieval',asrsTarget:{index:0},nodeEnteredAt:0,readyAt:0});engine.state.cadTokens=[token];engine.canAcceptNode=()=>true;engine.predictedEntryAvailable=()=>false;assert.equal(engine.tryDirectHandover(token),false);assert.equal(token.nodeId,'asrs');assert.ok(token.handoffAcceptedAt==null);assert.equal(engine.state.events.at(-1).type,'asrs-outfeed-preflight-wait');engine.predictedEntryAvailable=()=>true;assert.equal(engine.tryDirectHandover(token),false);assert.equal(token.transferState,'Transferring');assert.equal(token.handoffAcceptedAt,0);});

test('AS/RS 스태커 FSM은 하류 차량 도착 전 선행 인출 완료와 출고 위치 대기를 유지한다',()=>{const asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:1,rows:1,columns:2,levels:1}},amr={id:'amr',type:'amr',source:{origin:'dxf'},parameters:{}},edge={from:'asrs',to:'amr'},engine=new CadFlowEngine({equipment:[asrs,amr],cadSchematic:{edges:[edge],inboundBranches:[{name:'라인',nodeIds:[]}]}},{simDuration:10}),token=engine.prepareToken({id:1,nodeId:'asrs',edge,flowKey:'라인',stackerKey:'라인',cargoType:'박스',asrsPhase:'retrieval',nodeEnteredAt:0,readyAt:1,asrsTarget:{index:0}});engine.state.t=100;engine.state.cadTokens=[token];engine.updateAsrsStackerStates();const stacker=engine.state.asrs.stackers['라인'];assert.equal(stacker.activeTokenId,1);assert.equal(stacker.status,'outbound');assert.equal(stacker.phase,'handoff-wait');});

test('AS/RS는 물류 전체 인계 완료 확인 후에만 같은 스태커의 다음 셀 반출을 시작한다',()=>{const asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:1,rows:1,columns:2,levels:1,outfeedTime:.2,handoffConfirmTime:.5,batchReleaseEnabled:1,releaseBatchSize:1}},amr={id:'amr',type:'amr',source:{origin:'dxf'},parameters:{shuttleDistance:1,travelSpeed:1}},edge={from:'asrs',to:'amr'},engine=new CadFlowEngine({equipment:[asrs,amr],cadSchematic:{edges:[edge],inboundBranches:[{name:'라인',nodeIds:[]}]}},{simDuration:10}),outbound=engine.prepareToken({id:1,nodeId:'asrs',edge,flowKey:'라인',stackerKey:'라인',cargoType:'박스',asrsPhase:'retrieval',asrsTarget:{index:0},handoffAcceptedAt:0}),stored=engine.prepareToken({id:2,nodeId:'asrs',edge:null,flowKey:'라인',stackerKey:'라인',cargoType:'박스',asrsPhase:'stored',asrsTarget:{index:1},readyAt:Infinity}),zone=engine.state.asrs.zones['라인'];zone.inventory=2;zone.releaseRemaining=1;zone.occupiedSlots[0]=true;zone.occupiedSlots[1]=true;engine.asrsLineState('라인').mode='outbound';engine.state.t=.2;engine.state.cadTokens=[outbound,stored];engine.tryDirectHandover(outbound);assert.equal(outbound.nodeId,'amr');assert.equal(engine.asrsLineBusy('라인'),true);assert.equal(engine.scheduleAsrsBatchRetrieval(),false);assert.equal(stored.asrsPhase,'stored');engine.state.t=.71;assert.equal(engine.asrsLineBusy('라인'),false);assert.equal(engine.scheduleAsrsBatchRetrieval(),true);assert.equal(stored.asrsPhase,'retrieval');});

test('물류 중량과 설비 허용하중, 가동률·운전효율을 현장 보정에 반영한다',()=>{
  const layout={cargoSpec:{length:1200,width:800,weight:800,unit:'mm'}},conveyor={type:'conveyor',parameters:{length:5,speed:1,loadCapacity:700,availability:80,efficiency:75}};
  assert.equal(canEquipmentHandleCargo(conveyor,layout),false);
  assert.ok(Math.abs(equipmentAvailabilityFactor(conveyor)-.6)<1e-9);
  assert.ok(cadDuration(conveyor,layout)>6.2/.6);
});

test('포킹장치와 AMR은 받기·대기·이동·넘기기에 가감속 시간을 포함한다',()=>{const layout={cargoSpec:{length:1200,width:800,unit:'mm'}},fork={type:'forkingDevice',parameters:{strokeDistance:1.5,receiveSpeed:.5,holdTime:1,transferSpeed:.75}},amr={type:'amr',parameters:{shuttleDistance:6,receiveSpeed:.6,travelSpeed:1.5,transferSpeed:.4}},forkExpected=acceleratedTravelTime(1.5,.5,.8)+1+acceleratedTravelTime(1.5,.75,.8),amrExpected=acceleratedTravelTime(1.2,.6,.8)+acceleratedTravelTime(6,1.5,.8)+acceleratedTravelTime(1.2,.4,.8);assert.equal(cadDuration(fork,layout),forkExpected);assert.equal(cadDuration(amr,layout),amrExpected);});

test('입고 차량은 첫 컨베이어 안전 간격이 확보되면 AS/RS 적재 완료 전 다음 물류를 공급한다',()=>{const source={id:'in',type:'dock',source:{origin:'dxf'},parameters:{processTime:.2,dockRole:'inbound'}},cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:10,speed:1,safetyGap:.2}},asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:4,levels:1,productTypes:1,putawayTime:20}},engine=new CadFlowEngine({equipment:[source,cv,asrs],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[{from:'in',to:'cv'},{from:'cv',to:'asrs'}]}},{injectA:30,simDuration:6});for(let i=0;i<250;i++)engine.step(.02);assert.ok(engine.state.events.filter(event=>event.type==='source-injected').length>=2);assert.equal(engine.state.events.filter(event=>event.type==='asrs-putaway').length,0);});

test('AS/RS 입고·출고 전환은 두 인계 위치 사이 실제 이동과 확인시간을 기다린다',()=>{const storage={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:5,levels:2,infeedColumn:1,infeedLevel:1,outfeedColumn:5,outfeedLevel:2,columnPitch:2,levelHeight:2,travelSpeed:2,liftSpeed:1,downSpeed:1,acceleration:1,modeChangeTime:1}},engine=new CadFlowEngine({equipment:[storage],cadSchematic:{edges:[]}},{simDuration:20}),duration=asrsModeChangeDuration(storage,'outbound','inbound'),line=engine.asrsLineState('트림 라인');line.mode='outbound';assert.ok(duration>1);assert.equal(engine.ensureAsrsLineMode('트림 라인','inbound'),true);engine.state.t=duration-.01;assert.equal(engine.asrsLineBusy('트림 라인'),true);engine.state.t=duration+.01;assert.equal(engine.ensureAsrsLineMode('트림 라인','inbound'),false);assert.equal(line.mode,'inbound');});

test('비연속 설비는 인수·이동 또는 대기·인계 단계가 시간 순서대로 구분된다',()=>{const layout={cargoSpec:{length:1,width:.8}},fork={type:'forkingDevice',parameters:{strokeDistance:1,receiveSpeed:1,holdTime:2,transferSpeed:1}},token={nodeEnteredAt:0,operationDuration:4};assert.equal(equipmentSequenceSnapshot(fork,token,.5,layout).phase,'receive');assert.equal(equipmentSequenceSnapshot(fork,token,2,layout).phase,'move');assert.equal(equipmentSequenceSnapshot(fork,token,3.5,layout).phase,'transfer');});

test('포킹으로 다른 라인에 진입한 물류는 원래 품목색을 유지하고 도착 AS/RS 라인에 적재된다',()=>{const source={id:'src-a',type:'source',source:{origin:'dxf'}},infeed={id:'in-b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:2,speed:1}},asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:2,levels:1,productTypes:2,infeedTime:.1}},edge={from:'in-b',to:'asrs'},branches=[{name:'트림 라인',nodeIds:['src-a']},{name:'화이날 라인',nodeIds:['in-b']}],engine=new CadFlowEngine({equipment:[source,infeed,asrs],cadSchematic:{inboundBranches:branches,edges:[edge]}},{injectA:99,simDuration:10}),token=engine.prepareToken({id:1,nodeId:'in-b',edge,flowKey:'트림 라인',cargoType:'트림 물류',flowIndex:0,progress:1,readyAt:0,motion:null});engine.state.cadTokens=[token];engine.resolveZeroDelayHandovers();engine.state.t=.1;engine.resolveZeroDelayHandovers();assert.equal(token.originFlowKey,'트림 라인');assert.equal(token.cargoType,'트림 물류');assert.equal(token.flowKey,'화이날 라인');assert.equal(token.storageFlowKey,'화이날 라인');assert.equal(engine.state.asrs.zones['트림 라인'].inventory,0);assert.equal(engine.state.asrs.zones['화이날 라인'].inventory,1);});

test('분기 후 다른 라인 설비에 진입하는 즉시 품목 정체성은 유지하고 현재 라인을 갱신한다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf'},parameters:{}},b={id:'b',type:'conveyor',source:{origin:'dxf'},parameters:{}},branches=[{name:'트림 라인',nodeIds:['a']},{name:'화이날 라인',nodeIds:['b']}],engine=new CadFlowEngine({equipment:[a,b],cadSchematic:{inboundBranches:branches,edges:[]}},{simDuration:10}),token=engine.prepareToken({id:7,nodeId:'b',flowKey:'트림 라인',cargoType:'트림 물류',flowIndex:0});engine.state.cadTokens=[token];engine.updateTokenLineMembership();assert.equal(token.originFlowKey,'트림 라인');assert.equal(token.cargoType,'트림 물류');assert.equal(token.flowKey,'화이날 라인');assert.equal(token.flowIndex,1);assert.deepEqual(engine.state.events.at(-1),{t:0,type:'cargo-line-changed',productId:7,from:'트림 라인',to:'화이날 라인',cargoType:'트림 물류',equipmentId:'b'});});

test('컨베이어가 아닌 작업 설비는 작업 중 두 번째 물류를 받지 않는다',()=>{const source={id:'source',type:'source',source:{origin:'dxf'},parameters:{}},fork={id:'fork',type:'forkingDevice',source:{origin:'dxf'},parameters:{holdTime:5}},edge={from:'source',to:'fork'},engine=new CadFlowEngine({equipment:[source,fork],cadSchematic:{edges:[edge]}},{simDuration:10}),working=engine.prepareToken({id:1,nodeId:'fork',edge:null,readyAt:9}),incoming=engine.prepareToken({id:2,nodeId:'source',edge,readyAt:0});engine.state.cadTokens=[working,incoming];assert.equal(engine.tryDirectHandover(incoming),false);assert.equal(incoming.nodeId,'source');});

test('입고 시작 설비는 첫 컨베이어 진입부에 안전 공간이 생길 때만 다음 물류를 준비한다',()=>{const source={id:'source',type:'dock',source:{origin:'dxf'},parameters:{dockRole:'inbound',processTime:.1}},cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:10,speed:1,safetyGap:.2}},engine=new CadFlowEngine({equipment:[source,cv],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[{from:'source',to:'cv'}]}},{simDuration:10}),blocking=engine.prepareToken({id:1,nodeId:'cv',edge:null,progress:.1,readyAt:9});engine.state.cadTokens=[blocking];engine.injectAvailableSources();assert.equal(engine.state.cadTokens.length,1);blocking.progress=.5;engine.injectAvailableSources();assert.equal(engine.state.cadTokens.length,2);assert.equal(engine.state.cadTokens[1].nodeId,'source');});

test('서로 역방향 인계가 동시에 요청되면 먼저 요청한 한쪽만 통행권을 얻어 상호 교착 판정을 만들지 않는다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,safetyGap:.2}}),a=cv('a'),b=cv('b'),ab={from:'a',to:'b'},ba={from:'b',to:'a'},engine=new CadFlowEngine({equipment:[a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[ab,ba]}},{simDuration:10}),forward=engine.prepareToken({id:1,nodeId:'a',edge:ab,motion:engine.createMotion(a,6)}),reverse=engine.prepareToken({id:2,nodeId:'b',edge:ba,motion:engine.createMotion(b,4)});engine.state.cadTokens=[forward,reverse];assert.equal(engine.hasOpposingTransfer(ab,forward),false);assert.equal(engine.hasOpposingTransfer(ba,reverse),true);assert.equal(engine.tryDirectHandover(reverse),false);assert.equal(reverse.nodeId,'b');});

test('정지 상태가 된 예약 물류의 접근 승인은 즉시 회수되어 다른 합류 요청을 막지 않는다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}}),a=cv('a'),b=cv('b'),target=cv('target'),edgeA={from:'a',to:'target'},edgeB={from:'b',to:'target'},engine=new CadFlowEngine({equipment:[a,b,target],cadSchematic:{edges:[edgeA,edgeB]}},{simDuration:10}),stopped=engine.prepareToken({id:1,nodeId:'a',edge:null,queueState:'Queue',motion:engine.createMotion(a,5)}),ready=engine.prepareToken({id:2,nodeId:'b',edge:null,motion:engine.createMotion(b,5)});stopped.predictiveRouteEdge=edgeA;ready.predictiveRouteEdge=edgeB;engine.state.cadTokens=[stopped,ready];engine.approachGrants.set('target',{tokenId:stopped.id,fromId:'a',edge:edgeA,eta:0,grantedAt:0});engine.updatePredictiveReservations();assert.equal(engine.approachGrants.get('target')?.tokenId,ready.id);assert.equal(ready.handoffReserved,true);});

test('같은 컨베이어의 후속 물류는 선행 물류와 겹치기 전에 감속하고 절대 역주행하지 않는다',()=>{const cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:8,speed:2,acceleration:2,deceleration:2,jerk:8,safetyGap:.3}},layout={equipment:[cv],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[]}},engine=new CadFlowEngine(layout,{simDuration:4}),leader=engine.prepareToken({id:1,nodeId:'cv',edge:null,readyAt:99,motion:engine.createMotion(cv,2)}),follower=engine.prepareToken({id:2,nodeId:'cv',edge:null,readyAt:99,motion:engine.createMotion(cv,.2)});engine.state.cadTokens=[leader,follower];let previousFollower=follower.motion.controller.position;for(let index=0;index<150;index++){engine.step(.02);const positions=[leader,follower].map(token=>token.motion?.controller.position).filter(Number.isFinite).sort((a,b)=>b-a);if(positions.length===2)assert.ok(positions[0]-positions[1]>=1.3-1e-9);assert.ok((follower.motion?.controller.position??previousFollower)>=previousFollower-1e-9);previousFollower=follower.motion?.controller.position??previousFollower;}});

test('분기 출력 선택 순간부터 AS/RS까지 전체 경로를 도착 라인으로 고정한다',()=>{const equipment=['source','fork','shared-b','in-a','in-b'].map(id=>({id,type:id==='fork'?'forkingDevice':'conveyor',source:{origin:'dxf'},parameters:{}}));equipment.push({id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:2}});const branchA={from:'fork',to:'in-a'},branchB={from:'fork',to:'shared-b'},edges=[{from:'source',to:'fork'},branchA,branchB,{from:'shared-b',to:'in-b'},{from:'in-a',to:'asrs'},{from:'in-b',to:'asrs'}],branches=[{name:'트림 라인',nodeIds:['source','fork','shared-b','in-a']},{name:'화이날 라인',nodeIds:['in-b']}],engine=new CadFlowEngine({equipment,cadSchematic:{edges,inboundBranches:branches}},{simDuration:10}),token=engine.prepareToken({id:11,nodeId:'fork',edge:null,flowKey:'트림 라인',cargoType:'트림 물류',flowIndex:0});token.edge=branchB;assert.equal(token.originFlowKey,'트림 라인');assert.equal(token.cargoType,'트림 물류');assert.equal(token.flowKey,'화이날 라인');token.nodeId='shared-b';token.edge=null;engine.state.cadTokens=[token];engine.updateTokenLineMembership();assert.equal(token.flowKey,'화이날 라인');assert.equal(token.routeDestinationFlowKey,'화이날 라인');});

test('같은 입구 센서에 여러 설비가 요청하면 먼저 도착한 물류만 진입 허가를 받는다',()=>{const left={id:'left',type:'source',source:{origin:'dxf'},parameters:{}},right={id:'right',type:'source',source:{origin:'dxf'},parameters:{}},target={id:'target',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},edgeL={from:'left',to:'target'},edgeR={from:'right',to:'target'},engine=new CadFlowEngine({equipment:[left,right,target],cadSchematic:{edges:[edgeL,edgeR]}},{simDuration:10}),first=engine.prepareToken({id:1,nodeId:'left',edge:null}),second=engine.prepareToken({id:2,nodeId:'right',edge:null});first.edge=edgeL;second.edge=edgeR;engine.state.cadTokens=[second,first];assert.equal(first.transferState,'WaitingForInfeed');assert.equal(first.handover,null);assert.equal(engine.equipmentSensorState(target).firstRequestId,1);assert.equal(engine.tryDirectHandover(second),false);assert.equal(engine.tryDirectHandover(first),true);assert.equal(first.nodeId,'target');assert.equal(second.nodeId,'right');});

test('예측 핸드셰이크는 도착 예상시점의 B 입구 간격을 계산해 사전 예약한다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,deceleration:1}},b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,safetyGap:.2}},edge={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:10}),approaching=engine.prepareToken({id:1,nodeId:'a',edge:null,motion:engine.createMotion(a,4.9)}),ahead=engine.prepareToken({id:2,nodeId:'b',edge:null,motion:engine.createMotion(b,3)});approaching.motion.controller.velocity=1;ahead.motion.controller.velocity=1;engine.state.cadTokens=[approaching,ahead];engine.updatePredictiveReservations();assert.equal(approaching.handoffReservationRequired,true);assert.equal(approaching.handoffReserved,true);assert.equal(engine.transferReservations.get('b').tokenId,1);ahead.motion.controller.position=1.1;engine.updatePredictiveReservations();assert.equal(approaching.handoffReserved,false);});

test('분기에서 잠근 입고 라인은 AS/RS 직전 설비 소속으로 다시 덮어쓰지 않는다',()=>{const shared={id:'shared',type:'conveyor',source:{origin:'dxf'},parameters:{}},asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:2}},edge={from:'shared',to:'asrs'},branches=[{name:'A 라인',nodeIds:['shared']},{name:'B 라인',nodeIds:[]}],engine=new CadFlowEngine({equipment:[shared,asrs],cadSchematic:{edges:[edge],inboundBranches:branches}},{simDuration:10}),token=engine.prepareToken({id:1,nodeId:'shared',edge:null,flowKey:'B 라인',flowIndex:1,cargoType:'A 물류',routeDestinationFlowKey:'B 라인',routeDestinationFlowIndex:1});token.edge=edge;assert.equal(engine.assignAsrsDestinationLine(token),'B 라인');assert.equal(token.flowKey,'B 라인');});

test('AS/RS 출고는 보관 라인이 아니라 물류 종류에 대응하는 출고 라인을 선택한다',()=>{const asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:2}},trim={id:'trim-out',type:'dock',source:{origin:'dxf'},parameters:{dockRole:'outbound'}},final={id:'final-out',type:'dock',source:{origin:'dxf'},parameters:{dockRole:'outbound'}},edges=[{from:'asrs',to:'trim-out'},{from:'asrs',to:'final-out'}],lanes=[{name:'트림 라인',direction:'outbound',nodes:[trim]},{name:'화이날 라인',direction:'outbound',nodes:[final]}],engine=new CadFlowEngine({equipment:[asrs,trim,final],cadSchematic:{edges,lanes,inboundBranches:[{name:'트림 라인',nodeIds:[]},{name:'화이날 라인',nodeIds:[]}]}},{simDuration:10}),token={cargoType:'트림 물류',originFlowKey:'트림 라인',flowKey:'화이날 라인',flowIndex:1};assert.equal(engine.outboundLineForCargo(token).name,'트림 라인');token.outboundFlowKey='트림 라인';assert.equal(engine.selectRoute(edges,asrs,token),0);assert.equal(token.flowKey,'트림 라인');});

test('AS/RS 지정 출고 라인이 막혀도 다른 출고 라인으로 우회하지 않는다',()=>{const asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:2}},trim={id:'trim-out',type:'dock',source:{origin:'dxf'},parameters:{dockRole:'outbound'}},final={id:'final-out',type:'dock',source:{origin:'dxf'},parameters:{dockRole:'outbound'}},edges=[{from:'asrs',to:'trim-out'},{from:'asrs',to:'final-out'}],lanes=[{name:'트림 라인',direction:'outbound',nodes:[trim]},{name:'화이날 라인',direction:'outbound',nodes:[final]}],engine=new CadFlowEngine({equipment:[asrs,trim,final],cadSchematic:{edges,lanes,inboundBranches:[{name:'트림 라인',nodeIds:[]},{name:'화이날 라인',nodeIds:[]}]}},{simDuration:10}),blocker=engine.prepareToken({id:9,nodeId:'trim-out',edge:null,flowKey:'트림 라인',readyAt:99}),token={id:10,cargoType:'트림 물류',originFlowKey:'트림 라인',flowKey:'트림 라인',outboundFlowKey:'트림 라인',outboundFlowIndex:0};engine.state.cadTokens=[blocker];assert.equal(engine.routeCurrentlyAvailable(edges[0],token),false);assert.equal(engine.routeCurrentlyAvailable(edges[1],token),true);assert.equal(engine.selectRoute(edges,asrs,token),0);});

test('라인별 생성·ASRS 입고·출고 UPH를 서로 독립 집계한다',()=>{const source={id:'source',type:'source',source:{origin:'dxf'},parameters:{}},asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:2}},engine=new CadFlowEngine({equipment:[source,asrs],cadSchematic:{edges:[],inboundBranches:[{name:'A 라인',nodeIds:['source']},{name:'B 라인',nodeIds:[]}],lanes:[{name:'A 라인',direction:'outbound',nodes:[]},{name:'B 라인',direction:'outbound',nodes:[]}]}},{simDuration:100});engine.state.t=100;engine.state.events=[{type:'source-injected',flowKey:'A 라인'},{type:'source-injected',flowKey:'A 라인'},{type:'asrs-putaway',zone:'B 라인'},{type:'asrs-retrieval-start',outboundLine:'A 라인'}];const rows=Object.fromEntries(engine.getKpis().lineThroughput.map(row=>[row.name,row]));assert.equal(rows['A 라인'].generatedUph,72);assert.equal(rows['B 라인'].asrsInboundUph,36);assert.equal(rows['A 라인'].asrsOutboundUph,36);});

test('병렬 A-1·A-2가 B로 합류하면 예상 도착이 빠른 물류 하나만 선점한다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,deceleration:1}}),a1=cv('a1'),a2=cv('a2'),b=cv('b'),edges=[{from:'a1',to:'b'},{from:'a2',to:'b'}],engine=new CadFlowEngine({equipment:[a1,a2,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges}},{simDuration:10}),first=engine.prepareToken({id:1,nodeId:'a1',edge:null,createdAt:0,motion:engine.createMotion(a1,5.5)}),second=engine.prepareToken({id:2,nodeId:'a2',edge:null,createdAt:.1,motion:engine.createMotion(a2,5)});first.motion.controller.velocity=1;second.motion.controller.velocity=1;engine.state.cadTokens=[second,first];engine.updatePredictiveReservations();assert.equal(engine.approachGrants.get('b').tokenId,1);assert.equal(first.handoffReserved,true);assert.equal(second.handoffReserved,false);});

test('병렬 합류는 한 번에 한 진입만 허가하고 선행 물류 안전간격 확보 후 다음 라인을 허가한다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,deceleration:1,safetyGap:.2}}),a1=cv('a1'),a2=cv('a2'),b=cv('b'),edge1={from:'a1',to:'b'},edge2={from:'a2',to:'b'},engine=new CadFlowEngine({equipment:[a1,a2,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge1,edge2]}},{simDuration:10}),first=engine.prepareToken({id:1,nodeId:'a1',edge:null,createdAt:0,motion:engine.createMotion(a1,5.5)}),second=engine.prepareToken({id:2,nodeId:'a2',edge:null,createdAt:.1,motion:engine.createMotion(a2,5.5)});first.motion.controller.velocity=1;second.motion.controller.velocity=1;engine.state.cadTokens=[first,second];engine.updatePredictiveReservations();assert.equal(engine.approachGrants.size,1);assert.equal(first.handoffReserved,true);assert.equal(second.handoffReserved,false);first.edge=edge1;assert.equal(engine.tryDirectHandover(first),true);assert.equal(engine.tryDirectHandover(second),false);first.motion.controller.position=2.3;first.motionState=first.motion.controller.snapshot();engine.updatePredictiveReservations();assert.equal(engine.approachGrants.get('b').tokenId,second.id);assert.equal(second.handoffReserved,true);});

test('합류 진입권은 순간 ETA가 바뀌어도 인계 완료 전 다른 물류로 뒤집히지 않는다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:2,deceleration:1}}),a1=cv('a1'),a2=cv('a2'),b=cv('b'),edges=[{from:'a1',to:'b'},{from:'a2',to:'b'}],engine=new CadFlowEngine({equipment:[a1,a2,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges}},{simDuration:10}),first=engine.prepareToken({id:1,nodeId:'a1',edge:null,motion:engine.createMotion(a1,5.5)}),second=engine.prepareToken({id:2,nodeId:'a2',edge:null,motion:engine.createMotion(a2,5)});first.motion.controller.velocity=1;second.motion.controller.velocity=1;engine.state.cadTokens=[first,second];engine.updatePredictiveReservations();second.motion.controller.position=5.9;second.motion.controller.velocity=2;engine.updatePredictiveReservations();assert.equal(engine.approachGrants.get('b').tokenId,1);assert.equal(second.handoffReserved,false);});

test('분기 예정 경로도 실제 진입 전에 예약하여 다른 병렬 라인과 충돌하지 않는다',()=>{const fork={id:'fork',type:'forkingDevice',source:{origin:'dxf'},parameters:{output1Ratio:100}},a2={id:'a2',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},c={id:'c',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},toB={from:'fork',to:'b'},toC={from:'fork',to:'c'},a2B={from:'a2',to:'b'},engine=new CadFlowEngine({equipment:[fork,a2,b,c],cadSchematic:{edges:[toB,toC,a2B]}},{simDuration:10}),branching=engine.prepareToken({id:1,nodeId:'fork',edge:null,createdAt:0,readyAt:0}),parallel=engine.prepareToken({id:2,nodeId:'a2',edge:null,createdAt:1,motion:engine.createMotion(a2,5.5)});parallel.motion.controller.velocity=1;engine.state.cadTokens=[branching,parallel];engine.updatePredictiveReservations();assert.equal(branching.predictiveRouteEdge,toB);assert.equal(engine.approachGrants.get('b').tokenId,1);assert.equal(parallel.handoffReserved,false);});

test('연속 병렬 분기에서 한 번 선택한 경로는 하류 예약이 바뀌어도 인계 완료 전 다른 경로로 되돌리지 않는다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,continuousHandover:1}}),junction=cv('junction'),left=cv('left'),right=cv('right'),leftEdge={from:'junction',to:'left'},rightEdge={from:'junction',to:'right'},engine=new CadFlowEngine({equipment:[junction,left,right],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[leftEdge,rightEdge]}},{simDuration:10}),token=engine.prepareToken({id:1,nodeId:'junction',flowIndex:0,motion:engine.createMotion(junction,4.8)});engine.state.cadTokens=[token];assert.equal(engine.plannedEdgeForToken(token,junction,[leftEdge,rightEdge]),leftEdge);const blocker=engine.prepareToken({id:2,nodeId:'left',queueState:'Queue',motion:engine.createMotion(left,1)});engine.state.cadTokens.push(blocker);assert.equal(engine.plannedEdgeForToken(token,junction,[leftEdge,rightEdge]),leftEdge);assert.equal(token.routeIntentLocked,true);engine.updatePredictiveReservations();const before=token.motion.controller.position;engine.advanceMotion(token,junction,.2);assert.ok(token.motion.controller.position>=before);assert.ok(token.motion.controller.position<=5+1e-9);assert.equal(token.predictiveRouteEdge,leftEdge);});

test('대기 해제 후 다음 설비가 인수하면 이전 대기·예약·렌더 상태를 즉시 폐기한다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:2,speed:1}},b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:2,speed:1}},edge={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[a,b],cargoSpec:{length:.5,width:.4},cadSchematic:{edges:[edge]}},{simDuration:10}),token=engine.prepareToken({id:1,nodeId:'a',edge:null,motion:engine.createMotion(a),queueState:'Queue',blockedBy:'b',motionLimit:1,handoffReserved:true,handoffReservationRequired:true,predictiveRouteEdge:edge,operationStep:{phase:'waiting'}});token.edge=edge;token.nodeId='b';token.edge=null;assert.equal(token.transferState,'InfeedAccepted');assert.equal(token.queueState,null);assert.equal(token.blockedBy,null);assert.equal(token.motionLimit,null);assert.equal(token.handoffReserved,false);assert.equal(token.handoffReservationRequired,false);assert.equal(token.predictiveRouteEdge,null);assert.equal(token.operationStep,null);assert.equal(token.handover,null);assert.equal(token.incomingHandover.sourceId,'a');});

test('병렬 합류의 예약권자는 늦게 연결 요청했어도 먼저 B로 진입해 교착되지 않는다',()=>{const a1={id:'a1',type:'conveyor',source:{origin:'dxf'},parameters:{}},a2={id:'a2',type:'conveyor',source:{origin:'dxf'},parameters:{}},b={id:'b',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},edge1={from:'a1',to:'b'},edge2={from:'a2',to:'b'},engine=new CadFlowEngine({equipment:[a1,a2,b],cadSchematic:{edges:[edge1,edge2]}},{simDuration:10}),loser=engine.prepareToken({id:2,nodeId:'a2',edge:null}),winner=engine.prepareToken({id:1,nodeId:'a1',edge:null});loser.edge=edge2;winner.edge=edge1;engine.state.cadTokens=[loser,winner];engine.transferReservations.set('b',{tokenId:1,edge:edge1,eta:0});assert.equal(engine.firstTransferRequest('b'),winner);assert.equal(engine.tryDirectHandover(winner),true);assert.equal(winner.nodeId,'b');assert.equal(loser.nodeId,'a2');});

test('단독 설비의 물류가 출력단에서 대기 중이면 다음 물류 진입을 계속 차단한다',()=>{const source={id:'source',type:'conveyor',source:{origin:'dxf'},parameters:{}},fork={id:'fork',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},sink={id:'sink',type:'sink',source:{origin:'dxf'},parameters:{}},intoFork={from:'source',to:'fork'},outOfFork={from:'fork',to:'sink'},engine=new CadFlowEngine({equipment:[source,fork,sink],cadSchematic:{edges:[intoFork,outOfFork]}},{simDuration:10}),waiting=engine.prepareToken({id:1,nodeId:'fork',edge:outOfFork}),incoming=engine.prepareToken({id:2,nodeId:'source',edge:intoFork});engine.state.cadTokens=[waiting,incoming];assert.equal(engine.nodeOccupancy('fork'),1);assert.equal(engine.tryDirectHandover(incoming),false);assert.equal(incoming.nodeId,'source');});

test('B에 물류 전체가 진입하면 오래된 A→B 렌더 인계 기록을 즉시 만료한다',()=>{const b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:2,speed:1}},engine=new CadFlowEngine({equipment:[b],cargoSpec:{length:.5,width:.4},cadSchematic:{edges:[]}},{simDuration:10}),token=engine.prepareToken({id:1,nodeId:'b',edge:null,motion:engine.createMotion(b,.5),incomingHandover:{sourceId:'a',targetId:'b',edge:{from:'a',to:'b'}}});engine.state.cadTokens=[token];engine.updateActiveMotions(.02);assert.equal(token.incomingHandover,null);});

test('컨베이어 A의 두 물류는 순서대로 B로 나가고 입구가 비면 상류 물류를 안전간격으로 받는다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,safetyGap:.2,continuousHandover:1}}),up=cv('up'),a=cv('a'),b=cv('b'),upA={from:'up',to:'a'},aB={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[up,a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[upA,aB]}},{simDuration:10}),front=engine.prepareToken({id:1,nodeId:'a',edge:null,createdAt:0,readyAt:0,motion:engine.createMotion(a,6)}),rear=engine.prepareToken({id:2,nodeId:'a',edge:null,createdAt:1,readyAt:0,motion:engine.createMotion(a,4.7)}),incoming=engine.prepareToken({id:3,nodeId:'up',edge:null,createdAt:2,readyAt:0,motion:engine.createMotion(up,6)});incoming.edge=upA;engine.state.cadTokens=[front,rear,incoming];engine.step(.02);assert.equal(front.nodeId,'b');assert.equal(rear.nodeId,'a');assert.equal(rear.edge,null);assert.equal(incoming.nodeId,'a');const positions=[rear,incoming].map(token=>Number(token.motionState?.position)).sort((x,y)=>y-x);assert.ok(positions[0]-positions[1]>=1.2-1e-9);});
test('선행 물류가 갑자기 대기해도 후속 물류는 제어 한 주기 여유를 포함한 간격 전에 정지한다',()=>{const cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:8,speed:2,acceleration:4,deceleration:4,jerk:20,safetyGap:.2}},engine=new CadFlowEngine({equipment:[cv],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[]}},{simDuration:10}),leader=engine.prepareToken({id:1,nodeId:'cv',edge:null,readyAt:99,motion:engine.createMotion(cv,4)}),follower=engine.prepareToken({id:2,nodeId:'cv',edge:null,readyAt:99,motion:engine.createMotion(cv,2)});leader.motion.controller.velocity=0;follower.motion.controller.velocity=2;engine.state.cadTokens=[leader,follower];const minimum=engine.minimumFollowingSpacing(cv);assert.equal(minimum,1.24);for(let index=0;index<100;index++){engine.step(.02);assert.ok(leader.motion.controller.position-follower.motion.controller.position>=minimum-1e-9);}});

test('컨베이어 출구가 막히면 같은 벨트 위 모든 물류가 함께 정지하고 간격을 유지한다',()=>{const b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,acceleration:4,deceleration:4,jerk:20,safetyGap:.2}},c={id:'c',type:'forkingDevice',source:{origin:'dxf'},parameters:{holdTime:10}},edge={from:'b',to:'c'},engine=new CadFlowEngine({equipment:[b,c],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:10}),occupied=engine.prepareToken({id:1,nodeId:'c',edge:null,readyAt:99}),front=engine.prepareToken({id:2,nodeId:'b',edge,readyAt:0,motion:engine.createMotion(b,6)}),rear=engine.prepareToken({id:3,nodeId:'b',edge:null,readyAt:99,motion:engine.createMotion(b,3)});rear.motion.controller.velocity=0;engine.state.cadTokens=[occupied,front,rear];engine.applyOccupancyInterlocks(.02);const before=rear.motion.controller.position;engine.updateActiveMotions(.02);assert.equal(rear.beltInterlocked,true);assert.equal(rear.motion.controller.position,before);assert.ok(front.motion.controller.position-rear.motion.controller.position>=engine.minimumFollowingSpacing(b));});

test('단독 설비는 이전 물류의 꼬리 인계가 끝나기 전 다음 물류를 받지 않는다',()=>{const a={id:'a',type:'forkingDevice',source:{origin:'dxf'},parameters:{receiveSpeed:.5,holdTime:1,transferSpeed:.5,strokeDistance:1}},b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},up={id:'up',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},aB={from:'a',to:'b'},upA={from:'up',to:'a'},engine=new CadFlowEngine({equipment:[up,a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[upA,aB]}},{simDuration:10}),departed=engine.prepareToken({id:1,nodeId:'b',edge:null,motion:engine.createMotion(b,0),incomingHandover:{sourceId:'a',targetId:'b',edge:aB,acceptedAt:0}}),incoming=engine.prepareToken({id:2,nodeId:'up',edge:upA,readyAt:0,motion:engine.createMotion(up,6)});engine.state.cadTokens=[departed,incoming];assert.equal(engine.handoverSourceOccupied('a'),true);assert.equal(engine.tryDirectHandover(incoming),false);departed.motion.controller.position=1;departed.motionState=departed.motion.controller.snapshot();engine.updateActiveMotions(.02);assert.equal(engine.handoverSourceOccupied('a'),false);assert.equal(engine.tryDirectHandover(incoming),true);});

test('벨트 인터락은 감속 관성 없이 현재 위치에서 즉시 정지한다',()=>{const cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:2,acceleration:1,deceleration:1,jerk:1}},engine=new CadFlowEngine({equipment:[cv],cadSchematic:{edges:[]}},{simDuration:10}),token=engine.prepareToken({id:1,nodeId:'cv',edge:null,motion:engine.createMotion(cv,2)});token.motion.controller.velocity=2;token.motion.controller.acceleration=1;token.beltInterlocked=true;const before=token.motion.controller.position;engine.advanceMotion(token,cv,.02,true);assert.equal(token.motion.controller.position,before);assert.equal(token.motion.controller.velocity,0);assert.equal(token.motion.controller.acceleration,0);assert.equal(token.motionState.state,'Stopped');});

test('연속 이동이 해제된 정지 컨베이어는 빈 공간이 남아 있어도 상류 물류를 받지 않는다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,continuousHandover:0}},b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,continuousHandover:0}},edge={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:10}),stopped=engine.prepareToken({id:1,nodeId:'b',edge:null,motion:engine.createMotion(b,4),beltInterlocked:true}),incoming=engine.prepareToken({id:2,nodeId:'a',edge,readyAt:0,motion:engine.createMotion(a,6)});engine.state.cadTokens=[stopped,incoming];assert.equal(engine.conveyorEntryAvailable(b,incoming,edge),true);assert.equal(engine.tryDirectHandover(incoming),false);assert.equal(incoming.nodeId,'a');});

test('END 물류가 포크로 넘어가면 뒤 물류는 END까지 이동한 뒤 포크 작업 중 정지한다',()=>{const cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,safetyGap:.2}},fork={id:'fork',type:'forkingDevice',source:{origin:'dxf'},parameters:{receiveSpeed:.5,holdTime:2,transferSpeed:.5,strokeDistance:1}},edge={from:'cv',to:'fork'},engine=new CadFlowEngine({equipment:[cv,fork],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:10}),end=engine.prepareToken({id:1,nodeId:'cv',edge,readyAt:0,motion:engine.createMotion(cv,6)}),rear=engine.prepareToken({id:2,nodeId:'cv',edge:null,readyAt:0,motion:engine.createMotion(cv,3)});engine.state.cadTokens=[end,rear];assert.equal(engine.tryDirectHandover(end),true);assert.equal(end.nodeId,'fork');engine.applyOccupancyInterlocks(.02);assert.equal(rear.beltInterlocked,false);rear.motion.controller.position=rear.motion.distance;rear.motionState=rear.motion.controller.snapshot();engine.applyOccupancyInterlocks(.02);const before=rear.motion.controller.position;engine.updateActiveMotions(.02);assert.equal(rear.beltInterlocked,true);assert.equal(rear.motion.controller.position,before);});

test('AS/RS는 보관 라인이 같아도 물류 타입별 스태커를 독립 점유한다',()=>{const asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:2}},engine=new CadFlowEngine({equipment:[asrs],cadSchematic:{edges:[],inboundBranches:[{name:'공용 라인',nodeIds:[]}]}},{simDuration:10}),trim=engine.prepareToken({id:1,nodeId:'asrs',edge:null,flowKey:'공용 라인',cargoType:'트림',asrsPhase:'putaway',readyAt:9}),final=engine.prepareToken({id:2,nodeId:'asrs',edge:null,flowKey:'공용 라인',cargoType:'화이날',asrsPhase:'putaway',readyAt:9});engine.state.cadTokens=[trim];assert.equal(engine.asrsLineBusy('트림'),true);assert.equal(engine.asrsLineBusy('화이날'),false);engine.state.cadTokens.push(final);assert.equal(engine.asrsLineBusy('화이날'),true);assert.notEqual(engine.asrsStackerKey(trim),engine.asrsStackerKey(final));});

test('물품 구분 수를 바꾸면 AS/RS 스태커 수도 동일하게 동적 재구성된다',()=>{const asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:4,stackerCount:1}},engine=new CadFlowEngine({equipment:[asrs],cadSchematic:{edges:[]}},{simDuration:10});assert.equal(engine.state.asrs.stackerCount,4);assert.equal(Object.keys(engine.state.asrs.stackers).length,4);assert.equal(asrs.parameters.stackerCount,4);asrs.parameters.productTypes=2;engine.reset();assert.equal(engine.state.asrs.stackerCount,2);assert.equal(Object.keys(engine.state.asrs.stackers).length,2);assert.equal(asrs.parameters.stackerCount,2);});

test('분기 하류가 둘이면 정지·점유된 출구 대신 실제 이동 가능한 출구를 선택한다',()=>{const fork={id:'fork',type:'forkingDevice',source:{origin:'dxf'},parameters:{output1Ratio:100}},blocked={id:'blocked',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},open={id:'open',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},edges=[{from:'fork',to:'blocked'},{from:'fork',to:'open'}],engine=new CadFlowEngine({equipment:[fork,blocked,open],cargoSpec:{length:1,width:.8},cadSchematic:{edges}},{simDuration:10}),waiting=engine.prepareToken({id:1,nodeId:'blocked',edge:{from:'blocked',to:'fork'},beltInterlocked:true}),cargo=engine.prepareToken({id:2,nodeId:'fork',edge:null,flowKey:'A',flowIndex:0});engine.state.cadTokens=[waiting,cargo];const options=engine.outgoing.get('fork');assert.equal(engine.selectRoute(options,fork,cargo),1);assert.equal(engine.plannedEdgeForToken(cargo,fork,options).to,'open');});

test('같은 컨베이어의 뒤 물류는 다른 분기 출구의 인계권을 선점하지 않는다',()=>{const cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,acceleration:1,deceleration:1}},left={id:'left',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},right={id:'right',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},edges=[{from:'cv',to:'left'},{from:'cv',to:'right'}],engine=new CadFlowEngine({equipment:[cv,left,right],cargoSpec:{length:1,width:.8},cadSchematic:{edges}},{simDuration:10}),front=engine.prepareToken({id:1,nodeId:'cv',edge:null,flowIndex:0,createdAt:0,motion:engine.createMotion(cv,5.8)}),rear=engine.prepareToken({id:2,nodeId:'cv',edge:null,flowIndex:1,createdAt:1,motion:engine.createMotion(cv,5.2)});engine.state.cadTokens=[front,rear];engine.updatePredictiveReservations();assert.equal(front.handoffReserved,true);assert.equal(rear.handoffReserved,false);assert.equal(rear.predictiveRouteEdge,null);assert.deepEqual([...engine.transferReservations.values()].map(value=>value.tokenId),[front.id]);front.nodeId='left';front.edge=null;engine.updatePredictiveReservations();assert.equal(rear.handoffReserved,true);assert.equal([...engine.transferReservations.values()].some(value=>value.tokenId===rear.id),true);});

test('하류가 실제 점유되어 출력 대기 중인 컨베이어는 빈 입구가 있어도 상류 인계를 거부한다',()=>{const up={id:'up',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},down={id:'down',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:8,speed:1}},sink={id:'sink',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},upDown={from:'up',to:'down'},downSink={from:'down',to:'sink'},engine=new CadFlowEngine({equipment:[up,down,sink],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[upDown,downSink]}},{simDuration:10}),occupied=engine.prepareToken({id:1,nodeId:'sink',edge:null,readyAt:99}),atExit=engine.prepareToken({id:2,nodeId:'down',edge:downSink,motion:engine.createMotion(down,9)}),incoming=engine.prepareToken({id:3,nodeId:'up',edge:upDown,motion:engine.createMotion(up,6)});engine.state.cadTokens=[occupied,atExit,incoming];engine.applyOccupancyInterlocks(.02);assert.equal(engine.conveyorEntryAvailable(down,incoming,upDown),true);assert.equal(engine.conveyorBeltStopped(down),true);assert.equal(engine.tryDirectHandover(incoming),false);});

test('컨베이어 출력 요청의 하류가 수용 가능하면 벨트를 멈추지 않고 빈 입구로 상류 물류를 받는다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:8,speed:1,safetyGap:.2}}),up=cv('up'),down=cv('down'),sink={id:'sink',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},upDown={from:'up',to:'down'},downSink={from:'down',to:'sink'},engine=new CadFlowEngine({equipment:[up,down,sink],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[upDown,downSink]}},{simDuration:10}),departing=engine.prepareToken({id:1,nodeId:'down',edge:downSink,motion:engine.createMotion(down,9)}),incoming=engine.prepareToken({id:2,nodeId:'up',edge:upDown,motion:engine.createMotion(up,9)});engine.state.cadTokens=[departing,incoming];engine.transferReservations.set('sink',{tokenId:departing.id,edge:downSink,eta:0});engine.applyOccupancyInterlocks(.02);assert.equal(engine.conveyorBeltStopped(down),false);engine.transferReservations.set('down',{tokenId:incoming.id,edge:upDown,eta:0});assert.equal(engine.tryDirectHandover(incoming),true);assert.equal(incoming.nodeId,'down');});

test('서로 다른 물품 타입은 같은 AS/RS에서도 각 전용 스태커로 동시에 입고한다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf'},parameters:{}},b={id:'b',type:'conveyor',source:{origin:'dxf'},parameters:{}},asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:2,rows:1,columns:2,levels:1,infeedTime:.1}},edgeA={from:'a',to:'asrs'},edgeB={from:'b',to:'asrs'},branches=[{name:'트림 라인',nodeIds:['a']},{name:'화이날 라인',nodeIds:['b']}],engine=new CadFlowEngine({equipment:[a,b,asrs],cadSchematic:{edges:[edgeA,edgeB],inboundBranches:branches}},{simDuration:10}),trim=engine.prepareToken({id:1,nodeId:'a',edge:edgeA,flowKey:'트림 라인',cargoType:'트림 물류'}),final=engine.prepareToken({id:2,nodeId:'b',edge:edgeB,flowKey:'화이날 라인',cargoType:'화이날 물류'});engine.state.cadTokens=[trim,final];engine.resolveZeroDelayHandovers();engine.state.t=.1;engine.resolveZeroDelayHandovers();assert.equal(trim.nodeId,'asrs');assert.equal(final.nodeId,'asrs');assert.equal(trim.asrsPhase,'putaway');assert.equal(final.asrsPhase,'putaway');assert.notEqual(trim.stackerKey,final.stackerKey);});

test('AS/RS 독립 스태커 FSM은 동시에 작업 중인 물류 ID와 목표 셀을 따로 유지한다',()=>{const asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:2}},engine=new CadFlowEngine({equipment:[asrs],cadSchematic:{edges:[],inboundBranches:[{name:'A 라인',nodeIds:[]},{name:'B 라인',nodeIds:[]}]}},{simDuration:10}),a=engine.prepareToken({id:1,nodeId:'asrs',edge:null,flowKey:'A 라인',cargoType:'A 물류',stackerKey:'A 라인',asrsPhase:'putaway',asrsTarget:{index:1}}),b=engine.prepareToken({id:2,nodeId:'asrs',edge:null,flowKey:'B 라인',cargoType:'B 물류',stackerKey:'B 라인',asrsPhase:'retrieval',asrsTarget:{index:2}});engine.state.cadTokens=[a,b];engine.updateAsrsStackerStates();assert.deepEqual(Object.values(engine.state.asrs.stackers).map(item=>item.activeTokenId),[1,2]);assert.deepEqual(Object.values(engine.state.asrs.stackers).map(item=>item.status),['inbound','outbound']);assert.deepEqual(Object.values(engine.state.asrs.stackers).map(item=>item.target.index),[1,2]);});

test('동시에 도착한 서로 다른 AS/RS 스태커 요청은 각각 별도 진입 예약을 받는다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:1,speed:1}}),a=cv('a'),b=cv('b'),asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:2}},edges=[{from:'a',to:'asrs'},{from:'b',to:'asrs'}],engine=new CadFlowEngine({equipment:[a,b,asrs],cadSchematic:{edges,inboundBranches:[{name:'A 라인',nodeIds:['a']},{name:'B 라인',nodeIds:['b']}]}},{simDuration:10}),first=engine.prepareToken({id:1,nodeId:'a',edge:null,flowKey:'A 라인',cargoType:'A 물류',motion:engine.createMotion(a,1)}),second=engine.prepareToken({id:2,nodeId:'b',edge:null,flowKey:'B 라인',cargoType:'B 물류',motion:engine.createMotion(b,1)});engine.state.cadTokens=[first,second];engine.updatePredictiveReservations();assert.equal(engine.approachGrants.size,2);assert.equal(first.handoffReserved,true);assert.equal(second.handoffReserved,true);assert.ok(engine.approachGrants.has('asrs:A 라인'));assert.ok(engine.approachGrants.has('asrs:B 라인'));});

test('연속 이동이 해제된 하류 컨베이어의 물류가 정지하면 빈 진입 공간이 있어도 상류 인계를 차단한다',()=>{const up={id:'up',type:'conveyor',source:{origin:'dxf'},parameters:{length:5,continuousHandover:0}},down={id:'down',type:'conveyor',source:{origin:'dxf'},parameters:{length:8,continuousHandover:0}},edge={from:'up',to:'down'},engine=new CadFlowEngine({equipment:[up,down],cadSchematic:{edges:[edge]}},{simDuration:10}),waiting=engine.prepareToken({id:1,nodeId:'down',edge:null,queueState:'Queue',motion:engine.createMotion(down,7)}),incoming=engine.prepareToken({id:2,nodeId:'up',edge,progress:1,motion:engine.createMotion(up,6)});engine.state.cadTokens=[waiting,incoming];assert.equal(engine.conveyorEntryAvailable(down,incoming,edge),true);assert.equal(engine.conveyorBeltStopped(down),false);assert.equal(engine.conveyorHasStoppedCargo(down,incoming),true);assert.equal(engine.tryDirectHandover(incoming),false);assert.equal(incoming.nodeId,'up');waiting.queueState=null;engine.transferReservations.set('down',{tokenId:incoming.id,edge,eta:0});assert.equal(engine.tryDirectHandover(incoming),true);assert.equal(incoming.nodeId,'down');});

test('연속 이동 체크 시 하류 끝단 물류가 대기해도 입구 공간만큼 후속 물류를 누적한다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:8,speed:1,continuousHandover:1}}),up=cv('up'),down=cv('down'),sink={id:'sink',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},upDown={from:'up',to:'down'},downSink={from:'down',to:'sink'},engine=new CadFlowEngine({equipment:[up,down,sink],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[upDown,downSink]}},{simDuration:10}),occupied=engine.prepareToken({id:1,nodeId:'sink',edge:null,readyAt:99}),waiting=engine.prepareToken({id:2,nodeId:'down',edge:downSink,progress:1,motion:engine.createMotion(down,9)}),incoming=engine.prepareToken({id:3,nodeId:'up',edge:null,motion:engine.createMotion(up,7.9)});incoming.motion.controller.velocity=1;engine.state.cadTokens=[occupied,waiting,incoming];assert.ok(engine.nodeOccupancy('down')<engine.equipmentCapacity(down));assert.equal(engine.conveyorEntryAvailable(down,incoming,upDown),true);assert.equal(engine.conveyorHasStoppedCargo(down,incoming),true);engine.updatePredictiveReservations();assert.equal(incoming.handoffReserved,true);incoming.edge=upDown;assert.equal(engine.tryDirectHandover(incoming),true);assert.equal(incoming.nodeId,'down');});

test('연속 이동 체크 컨베이어는 출고단 대기 중에도 후속 물류를 안전간격 위치까지 채운다',()=>{const cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:8,speed:1,continuousHandover:1,safetyGap:.2}},sink={id:'sink',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},edge={from:'cv',to:'sink'},engine=new CadFlowEngine({equipment:[cv,sink],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:10}),occupied=engine.prepareToken({id:1,nodeId:'sink',edge:null,readyAt:99}),front=engine.prepareToken({id:2,nodeId:'cv',edge,motion:engine.createMotion(cv,9)}),following=engine.prepareToken({id:3,nodeId:'cv',edge:null,motion:engine.createMotion(cv,1)});following.motion.controller.velocity=1;engine.state.cadTokens=[occupied,front,following];engine.applyOccupancyInterlocks(.02);const before=following.motion.controller.position;assert.equal(engine.state.locks.conveyor.cv,true);assert.equal(following.beltInterlocked,false);engine.updateActiveMotions(.02);assert.ok(following.motion.controller.position>before);assert.ok(following.motionLimit>before);});

test('PLC 연쇄 핸드셰이크는 연속 이동 해제 시 하류가 곧 막힐 상황을 예측해 상류 인계를 보류한다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,continuousHandover:0,deceleration:2}}),a=cv('a'),b=cv('b'),c={id:'c',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},ab={from:'a',to:'b'},bc={from:'b',to:'c'},engine=new CadFlowEngine({equipment:[a,b,c],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[ab,bc]}},{simDuration:10}),occupied=engine.prepareToken({id:1,nodeId:'c',edge:null,readyAt:99}),downstream=engine.prepareToken({id:2,nodeId:'b',edge:null,motion:engine.createMotion(b,4.7)}),upstream=engine.prepareToken({id:3,nodeId:'a',edge:null,motion:engine.createMotion(a,4.9)});downstream.motion.controller.velocity=1;upstream.motion.controller.velocity=1;engine.state.cadTokens=[occupied,downstream,upstream];engine.updatePredictiveReservations();assert.equal(engine.conveyorOutfeedWillBlock(b,.1,upstream),true);assert.equal(upstream.handoffReserved,false);engine.advanceMotion(upstream,a,.2);assert.equal(Boolean(upstream.handoverCommitted),false);assert.ok(upstream.motion.controller.position<=upstream.motion.distance);});

test('AS/RS 출고 인터락은 해당 스태커 입고 라인만 막고 다른 라인은 계속 인계한다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:3,speed:1}}),a=cv('line-a'),b=cv('line-b'),asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:2,rows:1,columns:2,levels:1,infeedTime:.1}},edgeA={from:'line-a',to:'asrs'},edgeB={from:'line-b',to:'asrs'},engine=new CadFlowEngine({equipment:[a,b,asrs],cadSchematic:{edges:[edgeA,edgeB],inboundBranches:[{name:'A 라인',nodeIds:['line-a']},{name:'B 라인',nodeIds:['line-b']}]}},{simDuration:10}),outboundA=engine.prepareToken({id:1,nodeId:'asrs',edge:null,flowKey:'A 라인',cargoType:'A 물류',stackerKey:'A 라인',asrsPhase:'retrieval',readyAt:9}),waitingA=engine.prepareToken({id:2,nodeId:'line-a',edge:edgeA,flowKey:'A 라인',cargoType:'A 물류',motion:engine.createMotion(a,4)}),movingB=engine.prepareToken({id:3,nodeId:'line-b',edge:edgeB,flowKey:'B 라인',cargoType:'B 물류',motion:engine.createMotion(b,4)});engine.state.cadTokens=[outboundA,waitingA,movingB];engine.resolveZeroDelayHandovers();engine.state.t=.1;engine.resolveZeroDelayHandovers();assert.equal(waitingA.nodeId,'line-a');assert.equal(waitingA.queueState,'ASRS작업대기');assert.equal(movingB.nodeId,'asrs');assert.equal(movingB.asrsPhase,'putaway');assert.equal(engine.asrsLineBusy('A 라인'),true);assert.equal(engine.asrsLineBusy('B 라인'),true);});

test('물류 패턴 식별값은 분기 뒤에도 유지되고 AS/RS 셀은 실제 진입 라인에 귀속된다',()=>{const origin={id:'origin',type:'source',source:{origin:'dxf'}},infeed={id:'final-in',type:'conveyor',source:{origin:'dxf'},parameters:{}},asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:2}},edge={from:'final-in',to:'asrs'},engine=new CadFlowEngine({equipment:[origin,infeed,asrs],cargoPatternColors:{'파란 박스':'#123abc'},cadSchematic:{edges:[edge],inboundBranches:[{name:'원래 라인',nodeIds:['origin']},{name:'실제 진입 라인',nodeIds:['final-in']}]}},{simDuration:10}),token=engine.prepareToken({id:1,nodeId:'final-in',edge:null,flowKey:'원래 라인',originFlowKey:'원래 라인',cargoType:'파란 박스',cargoPatternKey:'파란 박스'});token.edge=edge;assert.equal(token.cargoPatternKey,'파란 박스');assert.equal(token.flowKey,'실제 진입 라인');assert.equal(token.storageFlowKey,'실제 진입 라인');assert.equal(token.asrsInboundFlowKey,'실제 진입 라인');});

test('물류 대기 시작과 해제를 한 번씩 기록하고 TXT 진단 로그에 정지 사유를 포함한다',()=>{const cv={id:'cv',name:'입고 컨베이어',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},engine=new CadFlowEngine({name:'진단 프로젝트',equipment:[cv],cadSchematic:{edges:[]}},{simDuration:10}),token=engine.prepareToken({id:7,nodeId:'cv',edge:null,queueState:'Queue',motion:engine.createMotion(cv,2)});engine.state.cadTokens=[token];engine.updateWaitDiagnostics();engine.updateWaitDiagnostics();assert.equal(engine.state.events.filter(event=>event.type==='cargo-wait-started').length,1);token.queueState=null;engine.updateWaitDiagnostics();assert.equal(engine.state.events.filter(event=>event.type==='cargo-wait-ended').length,1);token.queueState='Queue';engine.updateWaitDiagnostics();const text=simulationEventText(engine.state,engine.layout);assert.match(text,/진단 프로젝트/);assert.match(text,/선행 물류 안전간격 확보 대기/);assert.match(text,/입고 컨베이어/);assert.match(text,/물류=#7/);assert.match(text,/현재 대기\/정지 상태/);});

test('같은 스태커의 선행 반출 물류가 AS/RS 출구에 남아 있으면 다음 셀 반출을 시작하지 않는다',()=>{const asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:1,batchReleaseEnabled:1,releaseBatchSize:1}},out={id:'out',type:'amr',source:{origin:'dxf'},parameters:{}},engine=new CadFlowEngine({equipment:[asrs,out],cadSchematic:{edges:[{from:'asrs',to:'out'}],inboundBranches:[{name:'A 라인',nodeIds:[]}]}},{simDuration:10}),zone=engine.state.asrs.zones['A 라인'],pending=engine.prepareToken({id:1,nodeId:'asrs',edge:{from:'asrs',to:'out'},flowKey:'A 라인',stackerKey:'A 라인',asrsPhase:'retrieval',asrsTarget:{index:0}}),stored=engine.prepareToken({id:2,nodeId:'asrs',edge:null,flowKey:'A 라인',stackerKey:'A 라인',asrsPhase:'stored',asrsTarget:{index:1},readyAt:Infinity});zone.inventory=2;zone.releaseRemaining=1;zone.occupiedSlots[0]=true;zone.occupiedSlots[1]=true;engine.state.asrs.inventory=2;engine.state.cadTokens=[pending,stored];engine.asrsLineState('A 라인').mode='outbound';assert.equal(engine.asrsLineBusy('A 라인'),true);assert.equal(engine.scheduleAsrsBatchRetrieval(),false);assert.equal(stored.asrsPhase,'stored');});

test('점유 플래그가 없는 빈 AS/RS 셀의 저장 토큰은 반출 후보에서 제외한다',()=>{const asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{productTypes:1,batchReleaseEnabled:1,releaseBatchSize:1}},out={id:'out',type:'sink',source:{origin:'dxf'},parameters:{}},engine=new CadFlowEngine({equipment:[asrs,out],cadSchematic:{edges:[{from:'asrs',to:'out'}],inboundBranches:[{name:'A 라인',nodeIds:[]}]}},{simDuration:10}),zone=engine.state.asrs.zones['A 라인'],ghost=engine.prepareToken({id:9,nodeId:'asrs',edge:null,flowKey:'A 라인',stackerKey:'A 라인',asrsPhase:'stored',asrsTarget:{index:0},readyAt:Infinity});zone.inventory=1;zone.releaseRemaining=1;zone.occupiedSlots[0]=false;engine.state.asrs.inventory=1;engine.state.cadTokens=[ghost];engine.asrsLineState('A 라인').mode='outbound';assert.equal(engine.scheduleAsrsBatchRetrieval(),false);assert.equal(ghost.asrsPhase,'stored');assert.equal(engine.state.events.some(event=>event.type==='asrs-retrieval-start'),false);});

test('복수 상류가 연결된 컨베이어도 실제 길이만큼 적재하고 빈 진입 공간 수량만 순차 수용한다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,safetyGap:.2}}),a1=cv('a1'),a2=cv('a2'),b=cv('b'),edge1={from:'a1',to:'b'},edge2={from:'a2',to:'b'},engine=new CadFlowEngine({equipment:[a1,a2,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge1,edge2]}},{simDuration:10}),front=engine.prepareToken({id:1,nodeId:'b',edge:null,motion:engine.createMotion(b,4.8)}),first=engine.prepareToken({id:2,nodeId:'a1',edge:edge1,motion:engine.createMotion(a1,6)}),second=engine.prepareToken({id:3,nodeId:'a2',edge:edge2,motion:engine.createMotion(a2,6)});engine.state.cadTokens=[front,first,second];assert.equal(engine.equipmentCapacity(b),4);engine.transferReservations.set('b',{tokenId:first.id,edge:edge1,eta:0});assert.equal(engine.tryDirectHandover(first),true);assert.equal(first.nodeId,'b');assert.equal(engine.tryDirectHandover(second),false);first.motion.controller.position=2.3;first.motionState=first.motion.controller.snapshot();engine.transferReservations.set('b',{tokenId:second.id,edge:edge2,eta:0});assert.equal(engine.tryDirectHandover(second),true);assert.equal(second.nodeId,'b');assert.equal(engine.nodeOccupancy('b'),3);});

test('하류가 실제로 받을 수 없으면 물류 머리는 컨베이어 경계를 넘지 않는다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:2,continuousHandover:1}},b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,safetyGap:.2}},edge={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:10}),approaching=engine.prepareToken({id:1,nodeId:'a',edge:null,motion:engine.createMotion(a,4.99)}),blocked=engine.prepareToken({id:2,nodeId:'b',edge:null,motion:engine.createMotion(b,1.1)});approaching.motion.controller.velocity=2;engine.state.cadTokens=[approaching,blocked];engine.updatePredictiveReservations();engine.advanceMotion(approaching,a,.1);assert.equal(approaching.handoverCommitted,false);assert.ok(approaching.motion.controller.position<=5);});

test('경계를 넘기 전 하류가 정지하면 사전 승인을 취소하고 상류 끝단에서 대기한다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,continuousHandover:1}},b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,safetyGap:.2}},edge={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:10}),approaching=engine.prepareToken({id:1,nodeId:'a',edge:null,motion:engine.createMotion(a,4.99)}),ahead=engine.prepareToken({id:2,nodeId:'b',edge:null,motion:engine.createMotion(b,3)});approaching.motion.controller.velocity=1;engine.state.cadTokens=[approaching,ahead];engine.updatePredictiveReservations();engine.advanceMotion(approaching,a,.02);assert.equal(approaching.handoverCommitted,true);ahead.queueState='Queue';engine.updatePredictiveReservations();assert.equal(approaching.handoverCommitted,false);assert.equal(approaching.handoffReserved,false);engine.advanceMotion(approaching,a,.2);assert.ok(approaching.motion.controller.position<=5+1e-9);});

test('물류 머리가 실제 경계를 넘은 뒤에는 인계 예약을 유지해 역주행시키지 않는다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,continuousHandover:1}},b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,safetyGap:.2}},edge={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:10}),approaching=engine.prepareToken({id:1,nodeId:'a',edge:null,motion:engine.createMotion(a,5.01)}),ahead=engine.prepareToken({id:2,nodeId:'b',edge:null,motion:engine.createMotion(b,3)});approaching.predictiveRouteEdge=edge;approaching.handoverCommitted=true;engine.state.cadTokens=[approaching,ahead];engine.approachGrants.set('b',{tokenId:1,fromId:'a',edge,eta:0});ahead.queueState='Queue';engine.updatePredictiveReservations();assert.equal(engine.transferReservations.get('b').tokenId,approaching.id);assert.equal(approaching.handoffReserved,true);});

test('경계에 걸친 물류는 하류가 정지하면 양쪽 컨베이어를 함께 멈추고 같은 위치에서 재개한다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,continuousHandover:1}},b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,safetyGap:.2}},edge={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:10}),straddled=engine.prepareToken({id:1,nodeId:'a',edge:null,motion:engine.createMotion(a,5.2)}),blocked=engine.prepareToken({id:2,nodeId:'b',edge:null,queueState:'Queue',motion:engine.createMotion(b,3)}),other=engine.prepareToken({id:3,nodeId:'a',edge:null,motion:engine.createMotion(a,2)});straddled.predictiveRouteEdge=edge;straddled.handoverCommitted=true;straddled.handoffReserved=true;straddled.motion.controller.velocity=1;engine.state.cadTokens=[straddled,blocked,other];const stoppedAt=straddled.motion.controller.position;engine.advanceMotion(straddled,a,.2);assert.equal(straddled.handoverStraddled,true);assert.equal(straddled.motion.controller.position,stoppedAt);assert.equal(straddled.motion.controller.velocity,0);assert.equal(engine.conveyorBeltStopped(a),true);assert.equal(engine.conveyorBeltStopped(b),true);blocked.queueState=null;engine.state.locks.conveyor.a=false;engine.state.locks.conveyor.b=false;engine.advanceMotion(straddled,a,.2);assert.equal(straddled.handoverStraddled,false);assert.ok(straddled.motion.controller.position>stoppedAt);});

test('PLC 스캔은 하류 상태 계산 후 인계 승인을 계산한다',()=>{const cv={id:'cv',type:'conveyor',source:{origin:'dxf'},parameters:{length:5}},engine=new CadFlowEngine({equipment:[cv],cadSchematic:{edges:[]}},{simDuration:1}),calls=[],apply=engine.applyOccupancyInterlocks.bind(engine),reserve=engine.updatePredictiveReservations.bind(engine);engine.applyOccupancyInterlocks=dt=>{calls.push('interlock');return apply(dt);};engine.updatePredictiveReservations=()=>{calls.push('approval');return reserve();};engine.stabilizeFlowPermissions(.02);assert.deepEqual(calls.slice(0,2),['interlock','approval']);});

test('연속 이동 체크 시 최하류가 막혀도 중간 컨베이어의 빈 입구까지는 누적 수용한다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,continuousHandover:1}}),a=cv('a'),b=cv('b'),c={id:'c',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},ab={from:'a',to:'b'},bc={from:'b',to:'c'},engine=new CadFlowEngine({equipment:[a,c,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[ab,bc]}},{simDuration:10}),occupied=engine.prepareToken({id:1,nodeId:'c',edge:null,readyAt:99}),atBEnd=engine.prepareToken({id:2,nodeId:'b',edge:bc,motion:engine.createMotion(b,5)}),atAEnd=engine.prepareToken({id:3,nodeId:'a',edge:null,motion:engine.createMotion(a,5)});engine.state.cadTokens=[occupied,atBEnd,atAEnd];engine.stabilizeFlowPermissions(.02);assert.equal(engine.state.locks.conveyor.b,true);assert.equal(engine.state.locks.conveyor.a,false);assert.equal(engine.canAcceptNode(b,atAEnd,ab),true);});

test('컨베이어 정지 판정은 물류 꼬리 이동거리 대신 실제 설비 끝단을 사용한다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},blocked={id:'blocked',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},edge={from:'a',to:'blocked'},engine=new CadFlowEngine({equipment:[a,blocked],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:10}),occupied=engine.prepareToken({id:1,nodeId:'blocked',edge:null,readyAt:99}),front=engine.prepareToken({id:2,nodeId:'a',edge:null,motion:engine.createMotion(a,5)});engine.state.cadTokens=[occupied,front];assert.ok(front.motion.distance>5);engine.applyOccupancyInterlocks(.02);assert.equal(engine.state.locks.conveyor.a,true);});

test('진입 가능 수량은 운전·배출 허가와 점유 및 실제 예약 물류 수를 함께 차감한다',()=>{const b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:2.5,speed:1,safetyGap:.2}},up={id:'up',type:'conveyor',source:{origin:'dxf'},parameters:{length:5}},edge={from:'up',to:'b'},engine=new CadFlowEngine({equipment:[up,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:10}),reserved=engine.prepareToken({id:1,nodeId:'up',edge:null});engine.state.cadTokens=[reserved];engine.approachGrants.set('b',{tokenId:1,fromId:'up',edge,eta:1});engine.transferReservations.set('b',{tokenId:1,edge,eta:1});assert.equal(engine.equipmentCapacity(b),2);assert.equal(engine.reservedInboundCount('b'),1);assert.equal(engine.availableInboundSlots(b),1);engine.state.locks.conveyor={b:true};assert.equal(engine.availableInboundSlots(b),0);});

test('인계 승인 취소 로그는 취소 사유와 실제 하류 차단 물류 번호를 기록한다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},b={id:'b',name:'B 컨베이어',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},edge={from:'a',to:'b'},engine=new CadFlowEngine({name:'PLC 진단',equipment:[a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:10}),incoming=engine.prepareToken({id:10,nodeId:'a',edge:null,motion:engine.createMotion(a,4.9)}),blocker=engine.prepareToken({id:20,nodeId:'b',edge:null,motion:engine.createMotion(b,3)});incoming.motion.controller.velocity=1;engine.state.cadTokens=[incoming,blocker];engine.updatePredictiveReservations();assert.equal(incoming.handoffReserved,true);blocker.queueState='Queue';engine.updatePredictiveReservations();const event=engine.state.events.find(entry=>entry.type==='handover-cancelled');assert.equal(event.productId,10);assert.equal(event.blockerProductId,20);assert.match(event.reason,/하류 운전 허가/);assert.match(simulationEventText(engine.state,engine.layout),/차단물류=#20/);});

test('정지 상세 진단은 설비별 의도·점유·예약·차단 물류와 운동 상태를 출력한다',()=>{const a={id:'a',name:'상류 CV',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},b={id:'b',name:'하류 CV',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},edge={from:'a',to:'b'},engine=new CadFlowEngine({name:'정지 분석',equipment:[a,b],cadSchematic:{edges:[edge]}},{simDuration:10}),blocked=engine.prepareToken({id:20,nodeId:'b',edge:null,queueState:'Queue',motion:engine.createMotion(b,4)}),waiting=engine.prepareToken({id:10,nodeId:'a',edge:null,beltInterlocked:true,predictiveRouteEdge:edge,motion:engine.createMotion(a,5)});engine.state.cadTokens=[blocked,waiting];engine.state.locks.conveyor={a:true,b:true};engine.updateWaitDiagnostics();const text=engine.flowDiagnosticText();assert.match(text,/정지 분석/);assert.match(text,/상류 CV/);assert.match(text,/의도/);assert.match(text,/점유/);assert.match(text,/승인/);assert.match(text,/차단물류 20/);});

test('진행 가능한 작업이 전혀 없으면 정지 감지 이벤트를 한 번만 기록한다',()=>{const cv={id:'cv',type:'conveyor',source:{origin:'dxf'},parameters:{length:5}},engine=new CadFlowEngine({equipment:[cv],cadSchematic:{edges:[]}},{simDuration:10}),token=engine.prepareToken({id:1,nodeId:'cv',edge:null,queueState:'Queue',beltInterlocked:true,motion:engine.createMotion(cv,5)});engine.state.cadTokens=[token];for(let i=0;i<4;i++){engine.state.t=i;engine.updateStallDiagnostics();}assert.equal(engine.state.events.filter(event=>event.type==='simulation-stall-detected').length,1);assert.equal(engine.state.stall.active,true);});

test('다른 품목 스태커의 작업과 예약은 빈 트림 스태커 진입을 차단하지 않는다',()=>{const source={id:'src',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:2,speed:1}},asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:2,levels:1,productTypes:3}},edge={from:'src',to:'asrs'},engine=new CadFlowEngine({equipment:[source,asrs],cadSchematic:{inboundBranches:[{name:'트림 라인',nodeIds:['src']},{name:'화이날 라인',nodeIds:[]},{name:'도어 라인',nodeIds:[]}],edges:[edge]}}),trim=engine.prepareToken({id:3,nodeId:'src',flowKey:'트림 라인',edge}),final=engine.prepareToken({id:1,nodeId:'asrs',flowKey:'화이날 라인',stackerKey:'화이날 라인',asrsPhase:'retrieval'}),door=engine.prepareToken({id:2,nodeId:'asrs',flowKey:'도어 라인',stackerKey:'도어 라인',asrsPhase:'putaway'});engine.state.cadTokens=[final,door,trim];engine.transferReservations.set('asrs:화이날 라인',{tokenId:99,edge:{to:'asrs'}});engine.transferReservations.set('asrs:트림 라인',{tokenId:trim.id,edge});assert.equal(engine.availableInboundSlots(asrs,trim),1);assert.equal(engine.canAcceptNode(asrs,trim,edge),true);});

test('설비 인수 완료 시 이전 컨베이어의 벨트 정지 상태를 제거한다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:2,speed:1}},b={id:'b',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},edge={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[a,b],cadSchematic:{edges:[edge]}}),token=engine.prepareToken({id:1,nodeId:'a',edge,beltInterlocked:true});engine.state.cadTokens=[token];token.nodeId='b';assert.equal(token.beltInterlocked,false);assert.equal(token.nodeId,'b');});

test('AS/RS 보관 완료 물류의 오래된 접근 승인은 실제 출고 물류를 차단하지 않는다',()=>{const asrs={id:'asrs',type:'stackerCrane',source:{origin:'dxf'},parameters:{rows:1,columns:2,levels:1,productTypes:1}},cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:4,speed:1}},edge={from:'asrs',to:'cv'},engine=new CadFlowEngine({equipment:[asrs,cv],cadSchematic:{edges:[edge]}},{simDuration:10}),stored=engine.prepareToken({id:22,nodeId:'asrs',edge:null,asrsPhase:'stored',readyAt:Infinity}),outbound=engine.prepareToken({id:1,nodeId:'asrs',edge,asrsPhase:'retrieval',readyAt:0});engine.state.cadTokens=[stored,outbound];engine.approachGrants.set('cv',{tokenId:22,fromId:'asrs',edge,eta:0,grantedAt:0});engine.transferReservations.set('cv',{tokenId:22,edge,eta:0});engine.updatePredictiveReservations();assert.equal(engine.approachGrants.has('cv'),false);assert.equal(engine.transferReservations.get('cv')?.tokenId,1);assert.equal(engine.canAcceptNode(cv,outbound,edge),true);});

test('승인된 컨베이어 연속 인계는 설비 경계에서 감속하거나 한 프레임 정지하지 않는다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,continuousHandover:1,acceleration:2,deceleration:2,motionProfile:1}}),a=cv('a'),b=cv('b'),edge={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:20}),token=engine.prepareToken({id:1,nodeId:'a',readyAt:0,motion:engine.createMotion(a)});engine.state.cadTokens=[token];let minimumBoundarySpeed=Infinity;for(let i=0;i<400&&token.nodeId==='a';i++){engine.step(.02);const position=token.motion?.controller.position||0;if(position>=4.5)minimumBoundarySpeed=Math.min(minimumBoundarySpeed,token.motion.controller.velocity);}assert.equal(token.nodeId,'b');assert.ok(minimumBoundarySpeed>.95);assert.ok(token.motion.controller.velocity>.95);});

test('AGV와 AMR은 하류 인계 후 상류 대기점으로 복귀할 때까지 새 물류를 받지 않는다',()=>{const source={id:'source',type:'source',source:{origin:'dxf'},parameters:{}},agv={id:'agv',type:'agv',source:{origin:'dxf'},parameters:{shuttleDistance:5,travelSpeed:1,acceleration:1,deceleration:1}},sink={id:'sink',type:'sink',source:{origin:'dxf'},parameters:{}},edges=[{from:'source',to:'agv'},{from:'agv',to:'sink'}],engine=new CadFlowEngine({equipment:[source,agv,sink],cadSchematic:{edges}},{simDuration:20});engine.emit('sensor-outfeed',{equipmentId:'agv',productId:1,transferTo:'sink'});const returning=engine.state.mobileReturns.agv;assert.ok(returning.completedAt>engine.state.t);assert.equal(engine.availableInboundSlots(agv),0);engine.state.t=returning.completedAt;assert.equal(engine.availableInboundSlots(agv),1);});

test('연속 이동 체크 시 하류 입구 공간과 안전간격이 있으면 먼 하류 예측 차단 없이 인계한다',()=>{const cv=(id,continuous)=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:8,speed:1,safetyGap:.2,continuousHandover:continuous}}),a=cv('a',1),b=cv('b',1),blocked={id:'blocked',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},ab={from:'a',to:'b'},bb={from:'b',to:'blocked'},engine=new CadFlowEngine({equipment:[a,b,blocked],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[ab,bb]}},{simDuration:20}),occupied=engine.prepareToken({id:1,nodeId:'blocked',edge:null,readyAt:99}),front=engine.prepareToken({id:2,nodeId:'b',edge:null,motion:engine.createMotion(b,7.9)}),incoming=engine.prepareToken({id:3,nodeId:'a',edge:ab,motion:engine.createMotion(a,9)});front.motion.controller.velocity=1;engine.state.cadTokens=[occupied,front,incoming];engine.transferReservations.set('b',{tokenId:incoming.id,edge:ab,eta:0});assert.equal(engine.conveyorOutfeedWillBlock(b,0,incoming),true);assert.equal(engine.canAcceptNode(b,incoming,ab),true);assert.equal(engine.tryDirectHandover(incoming),true);assert.equal(incoming.nodeId,'b');});

test('연속 이동 해제 시에는 먼 하류 배출 가능 여부까지 PLC식으로 확인한다',()=>{const cv=(id,continuous)=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:8,speed:1,safetyGap:.2,continuousHandover:continuous}}),a=cv('a',0),b=cv('b',0),blocked={id:'blocked',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},ab={from:'a',to:'b'},bb={from:'b',to:'blocked'},engine=new CadFlowEngine({equipment:[a,b,blocked],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[ab,bb]}},{simDuration:20}),occupied=engine.prepareToken({id:1,nodeId:'blocked',edge:null,readyAt:99}),front=engine.prepareToken({id:2,nodeId:'b',edge:null,motion:engine.createMotion(b,7.9)}),incoming=engine.prepareToken({id:3,nodeId:'a',edge:ab,motion:engine.createMotion(a,9)});engine.state.cadTokens=[occupied,front,incoming];engine.transferReservations.set('b',{tokenId:incoming.id,edge:ab,eta:0});assert.equal(engine.conveyorOutfeedWillBlock(b,0,incoming),true);assert.equal(engine.canAcceptNode(b,incoming,ab),false);assert.equal(engine.tryDirectHandover(incoming),false);});

test('연속 이동 해제라도 PLC 인계가 승인되고 대기시간이 0초면 경계 속도를 유지한다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1,continuousHandover:0,handoverDelay:0,acceleration:2,deceleration:2,motionProfile:1}}),a=cv('a'),b=cv('b'),edge={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:20}),token=engine.prepareToken({id:1,nodeId:'a',readyAt:0,motion:engine.createMotion(a)});engine.state.cadTokens=[token];let minimumBoundarySpeed=Infinity;for(let i=0;i<400&&token.nodeId==='a';i++){engine.step(.02);const position=token.motion?.controller.position||0;if(position>=4.5)minimumBoundarySpeed=Math.min(minimumBoundarySpeed,token.motion.controller.velocity);}assert.equal(token.nodeId,'b');assert.ok(minimumBoundarySpeed>.95);assert.ok(token.motion.controller.velocity>.95);});

test('연속 이동 물류들은 물류 길이와 안전간격을 유지하면서 같은 벨트 속도로 추종한다',()=>{const cv={id:'cv',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:8,speed:1,safetyGap:.5,continuousHandover:1,acceleration:2,deceleration:2,motionProfile:1}},next={...cv,id:'next'},edge={from:'cv',to:'next'},engine=new CadFlowEngine({equipment:[cv,next],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:20}),spacing=engine.minimumFollowingSpacing(cv),leader=engine.prepareToken({id:1,nodeId:'cv',motion:engine.createMotion(cv,5)}),follower=engine.prepareToken({id:2,nodeId:'cv',motion:engine.createMotion(cv,5-spacing)});leader.motion.controller.velocity=1;follower.motion.controller.velocity=1;engine.state.cadTokens=[leader,follower];for(let i=0;i<50;i++){engine.applyOccupancyInterlocks(.02);engine.updateActiveMotions(.02);}const gap=leader.motion.controller.position-follower.motion.controller.position;assert.ok(gap>=spacing-1e-6);assert.ok(follower.motion.controller.velocity>.95);assert.equal(follower.queueState??null,null);});

test('연속 이동 체크 시 현재 입구가 좁아도 도착 예상 시점에 안전간격이 확보되면 사전 승인한다',()=>{const cv=id=>({id,type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:8,speed:1,safetyGap:.2,continuousHandover:1,acceleration:2,deceleration:2,motionProfile:1}}),a=cv('a'),b=cv('b'),edge={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:20}),spacing=engine.minimumFollowingSpacing(b),entry=conveyorEntryPosition(b,engine.layout),ahead=engine.prepareToken({id:1,nodeId:'b',motion:engine.createMotion(b,entry+spacing-.4)}),incoming=engine.prepareToken({id:2,nodeId:'a',motion:engine.createMotion(a,7.4)});ahead.motion.controller.velocity=1;incoming.motion.controller.velocity=1;engine.state.cadTokens=[ahead,incoming];assert.equal(engine.conveyorEntryAvailable(b,incoming,edge),false);assert.equal(engine.predictedEntryAvailable(b,edge,.6,incoming),true);engine.updatePredictiveReservations();assert.equal(incoming.handoffReserved,true);assert.equal(engine.approachGrants.get('b')?.tokenId,incoming.id);});

test('물류를 받는 하류 컨베이어에서 연속 이동을 체크해도 해당 연결을 연속 수용한다',()=>{const a={id:'a',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:8,speed:1,continuousHandover:0}},b={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:8,speed:1,continuousHandover:1}},edge={from:'a',to:'b'},engine=new CadFlowEngine({equipment:[a,b],cargoSpec:{length:1,width:.8},cadSchematic:{edges:[edge]}},{simDuration:20}),incoming=engine.prepareToken({id:1,nodeId:'a',edge,motion:engine.createMotion(a,9)});engine.state.cadTokens=[incoming];engine.transferReservations.set('b',{tokenId:incoming.id,edge,eta:0});assert.equal(engine.continuousConveyorLink(b,edge),true);assert.equal(engine.canAcceptNode(b,incoming,edge),true);assert.equal(engine.tryDirectHandover(incoming),true);assert.equal(incoming.nodeId,'b');});

test('빈 하류 설비의 예약 보유자는 다른 분기의 오래된 요청이 있어도 인계 승인을 유지한다',()=>{const sourceA={id:'a',type:'forkingDevice',source:{origin:'dxf'},parameters:{}},sourceB={id:'b',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},target={id:'target',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},edgeA={from:'a',to:'target'},edgeB={from:'b',to:'target'},engine=new CadFlowEngine({equipment:[sourceA,sourceB,target],cadSchematic:{edges:[edgeA,edgeB]}},{simDuration:20}),older=engine.prepareToken({id:4,nodeId:'a',edge:edgeA,readyAt:0}),holder=engine.prepareToken({id:8,nodeId:'b',edge:null,readyAt:0,motion:engine.createMotion(sourceB,5)});holder.predictiveRouteEdge=edgeB;engine.state.cadTokens=[older,holder];engine.transferReservations.set('target',{tokenId:holder.id,edge:edgeB,eta:0});assert.equal(engine.firstTransferRequest('target',holder),older);assert.equal(engine.canAcceptNode(target,holder,edgeB),true);engine.applyOccupancyInterlocks(.02);assert.equal(engine.state.locks.conveyor.b,false);assert.equal(holder.beltInterlocked,false);});

test('대기 진단은 분기 전체가 아니라 물류가 선택한 실제 경로의 차단자만 추적한다',()=>{const junction={id:'junction',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},blocked={id:'blocked',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},open={id:'open',type:'conveyor',source:{origin:'dxf',parameterLengthUnit:'m'},parameters:{length:5,speed:1}},blockedEdge={from:'junction',to:'blocked'},openEdge={from:'junction',to:'open'},engine=new CadFlowEngine({equipment:[junction,blocked,open],cadSchematic:{edges:[blockedEdge,openEdge]}},{simDuration:20}),waiting=engine.prepareToken({id:1,nodeId:'blocked',queueState:'Queue',motion:engine.createMotion(blocked,5)}),incoming=engine.prepareToken({id:2,nodeId:'junction',predictiveRouteEdge:openEdge,motion:engine.createMotion(junction,4)});engine.state.cadTokens=[waiting,incoming];assert.equal(engine.downstreamBlocker(junction,incoming),null);});
